/* ============================================================
   DESIGN TOKENS
   ink        #121210   near-black, primary text / primary surfaces
   paper      #FAFAF8   off-white, page background
   stone      #F0EEE9   quiet section background
   line       #E3E0D9   hairline borders
   graphite   #706C64   secondary text
   mist       #A7A29699 placeholder text
   brass      #A9803C   brand accent (from mark), used sparingly
   brassDeep  #7C5C28   accent on light backgrounds / text
   ============================================================ */
const T = {
  ink: "#111110",
  paper: "#FAFAF8",
  stone: "#F0EEE9",
  stoneDeep: "#E9E5DD",
  line: "#E3E0D9",
  graphite: "#706C64",
  mist: "#9C978D",
  brass: "#AD8642",
  brassSoft: "#D2B060",
  brassDeep: "#8E6F34",
  ok: "#3F6B4A",
};

/* Typography: a single technical sans-serif ("Inter") across every surface —
   nav, body, buttons, prices, and headlines. Hierarchy comes from weight,
   tracking and scale rather than switching typefaces, which keeps the site
   reading as a technology retailer rather than an editorial/fashion site. */
