/* ============================================================
   LIVE DATA STORE — a plain mutable mirror of the current
   products/units/categories, kept in sync by StoreDataProvider.
   Pure helper functions below read from here (not the SEED_
   constants) so every helper automatically sees admin edits
   without threading the arrays through every call site.
   ============================================================ */
const store = {
  products: [],
  units: [],
  categories: [],
};

const StoreDataContext = React.createContext(null);
function useStoreData() {
  return React.useContext(StoreDataContext);
}

/* A product is visible on the storefront unless an admin has set it
   to draft or hidden. Missing visibility (all seed data) defaults to
   published so nothing changes until an admin actually touches it. */
function isPublished(p) {
  return (p.visibility || "published") === "published";
}
function getSalesMode(p) {
  return p.salesMode || (p.status === "preorder" ? "reservation" : "for_sale");
}
function getAvailability(p) {
  if (p.availability) return p.availability;
  if (getSalesMode(p) === "reservation") return "coming_soon";
  return "in_stock";
}
/* Collections replace the old fixed featured/bestSeller/newArrival
   booleans with an open-ended list of merchandising tags a product
   can belong to. Products saved before this existed (or never
   touched in Admin) have no `collections` array yet, so we derive
   one from the legacy flags on read — nothing on the storefront
   breaks, and every product is automatically already a member of
   the right built-in collections. */
function getCollections(p) {
  if (p.collections && p.collections.length) return p.collections;
  const legacy = [];
  if (p.featured) legacy.push("featured");
  if (p.bestSeller) legacy.push("best-sellers");
  if (p.newArrival) legacy.push("new-arrivals");
  return legacy;
}
function hasCollection(p, id) {
  return getCollections(p).includes(id);
}
function getBadges(p) {
  const auto = [];
  if (getSalesMode(p) === "reservation") auto.push("PRE-ORDER");
  else if (hasCollection(p, "new-arrivals")) auto.push("NEW");
  else if (hasCollection(p, "best-sellers")) auto.push("BEST SELLER");
  const custom = p.badges || [];
  return Array.from(new Set([...auto, ...custom]));
}

/* ============================================================
   HELPERS
   ============================================================ */
function unitsFor(productId) {
  return store.units.filter((u) => u.productId === productId && u.availability === "available");
}
function priceFrom(product) {
  if (product.hasUnits) {
    const units = unitsFor(product.id);
    return units.length ? Math.min(...units.map((u) => u.price)) : null;
  }
  const vals = Object.values(product.variantPricing || {});
  return vals.length ? Math.min(...vals) : null;
}
function categoryLabel(key) {
  return store.categories.find((c) => c.key === key)?.label || key;
}
function conditionTone(cond) {
  if (cond === "New" || cond === "Excellent") return T.ok;
  if (cond === "Very Good") return T.brassDeep;
  return T.graphite;
}

/* ============================================================
   RECOMMENDATION ENGINE
   ============================================================ */
const REC_QUESTIONS = {
  budget: [
    { id: "b1", label: "Up to EGP 35,000", max: 35000 },
    { id: "b2", label: "Up to EGP 50,000", max: 50000 },
    { id: "b3", label: "Up to EGP 65,000", max: 65000 },
    { id: "b4", label: "EGP 65,000+", max: Infinity },
  ],
  priorities: [
    { id: "camera", label: "Camera" },
    { id: "battery", label: "Battery" },
    { id: "performance", label: "Performance" },
    { id: "gaming", label: "Gaming" },
    { id: "display", label: "Display" },
    { id: "value", label: "Value for money" },
  ],
  size: [
    { id: "compact", label: "Compact" },
    { id: "large", label: "Large" },
    { id: "any", label: "No preference" },
  ],
};

function computeRecommendation({ budgetMax, priorities, size }) {
  const candidates = store.products.filter((p) => p.category === "iphone" && p.rec && isPublished(p)).map((p) => ({
    ...p, _price: priceFrom(p),
  })).filter((p) => p._price != null && p._price <= budgetMax);

  const sized = candidates.filter((p) => {
    if (size === "compact") return p.screenSize <= 6.2;
    if (size === "large") return p.screenSize >= 6.5;
    return true;
  });

  const pool = sized.length ? sized : candidates;
  const keys = priorities.length ? priorities : ["value"];

  const scored = pool.map((p) => {
    const score = keys.reduce((s, k) => s + (p.rec[k] || 0), 0) / keys.length;
    return { ...p, _score: score };
  }).sort((a, b) => b._score - a._score || a._price - b._price);

  return scored;
}

/* ============================================================
   SMALL UI PRIMITIVES
   ============================================================ */
/* Shared enter/exit transition helper for drawers and sheets: keeps
   the panel mounted for `duration` ms after `isOpen` goes false so a
   closing animation can play instead of the panel vanishing instantly. */
function useMountTransition(isOpen, duration = 300) {
  const [mounted, setMounted] = useState(isOpen);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    let raf, timeout;
    if (isOpen) {
      setMounted(true);
      raf = requestAnimationFrame(() => setVisible(true));
    } else {
      setVisible(false);
      timeout = setTimeout(() => setMounted(false), duration);
    }
    return () => {
      if (raf) cancelAnimationFrame(raf);
      if (timeout) clearTimeout(timeout);
    };
  }, [isOpen, duration]);
  return [mounted, visible];
}

function Badge({ children, tone = "neutral" }) {
  const dot = { neutral: T.mist, brass: T.brass, live: T.ok }[tone];
  const text = { neutral: T.graphite, brass: T.brassDeep, live: T.ok }[tone];
  return (
    <span className="inline-flex items-center gap-1.5 text-xs font-medium" style={{ color: text }}>
      <span style={{ backgroundColor: dot }} className="w-1.5 h-1.5 rounded-full shrink-0" />
      {children}
    </span>
  );
}

function SectionHeading({ eyebrow, title, action, onAction }) {
  return (
    <div className="flex flex-wrap items-end justify-between mb-10 md:mb-12 gap-x-4 gap-y-2">
      <div>
        {eyebrow && <p style={{ color: T.graphite, fontSize: "13px", letterSpacing: "0.02em" }} className="mb-2">{eyebrow}</p>}
        <h2 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em", fontSize: "clamp(1.9rem, 3.2vw, 2.75rem)", lineHeight: 1.12 }}>{title}</h2>
      </div>
      {action && (
        <button onClick={onAction} className="group inline-flex items-center text-sm font-medium shrink-0 relative pb-1" style={{ color: T.ink }}>
          {action}
          <span className="absolute left-0 -bottom-0.5 h-px w-full" style={{ backgroundColor: T.line }} />
          <span className="absolute left-0 -bottom-0.5 h-px w-0 group-hover:w-full transition-all duration-300" style={{ backgroundColor: T.ink }} />
        </button>
      )}
    </div>
  );
}

/* ============================================================
   PRODUCT CARD
   ============================================================ */
function ProductCard({ product, onOpen, onToggleCompare, isComparing, compareDisabled }) {
  const price = priceFrom(product);
  const comparable = !["apple-accessory", "other-accessory"].includes(product.category);
  const badges = getBadges(product);
  const status = product.hasUnits ? "Certified pre-owned" : (badges[0] || null);
  const statusTone = getSalesMode(product) === "reservation" ? "brass" : hasCollection(product, "new-arrivals") ? "live" : "neutral";
  // For pre-owned models, surface the best-condition unit's headline spec on the card.
  const bestUnit = product.hasUnits
    ? unitsFor(product.id).slice().sort((a, b) => b.battery - a.battery)[0]
    : null;

  return (
    // NOTE: this outer element is a div, not a button element, precisely so
    // the independent compare control below can sit inside a clickable card
    // without nesting one interactive button inside another.
    <div className="group relative flex flex-col">
      <div
        role="button"
        tabIndex={0}
        onClick={() => onOpen(product.id)}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onOpen(product.id); } }}
        className="text-left w-full cursor-pointer"
      >
        <div style={{ backgroundColor: T.stone, aspectRatio: "1 / 1.05" }} className="relative w-full overflow-hidden">
          <ProductImage product={product} size={132} className="transition-transform duration-500 ease-out group-hover:scale-[1.04]" imgClassName="transition-transform duration-500 ease-out group-hover:scale-[1.04]" />
        </div>
        <div className="pt-3.5">
          {status && <p className="mb-1.5"><Badge tone={statusTone}>{status}</Badge></p>}
          <h3 style={{ color: T.ink, fontSize: "14.5px", letterSpacing: "-0.005em" }} className="font-medium leading-snug">{product.name}</h3>
          {bestUnit && (
            <p style={{ color: T.graphite }} className="text-xs mt-1.5 leading-relaxed">
              {bestUnit.storage} · {bestUnit.color}<br />{bestUnit.battery}% battery · {bestUnit.condition}
            </p>
          )}
          <p style={{ color: T.ink, fontVariantNumeric: "tabular-nums", fontWeight: 700, letterSpacing: "-0.005em" }} className="text-[15px] mt-2">
            {price != null ? CURRENCY(price) : "—"}
            {getSalesMode(product) === "reservation" && <span style={{ color: T.graphite, fontWeight: 400 }} className="text-xs ml-1.5">reserve</span>}
          </p>
        </div>
      </div>
      {comparable && (
        <button
          onClick={(e) => { e.stopPropagation(); onToggleCompare(product.id); }}
          disabled={!isComparing && compareDisabled}
          title={isComparing ? "Remove from compare" : "Add to compare"}
          style={{ backgroundColor: isComparing ? T.ink : "rgba(250,250,248,0.92)", color: isComparing ? "#fff" : T.ink, borderColor: T.line }}
          className="absolute top-3 right-3 w-8 h-8 rounded-full border flex items-center justify-center opacity-0 group-hover:opacity-100 focus:opacity-100 transition-opacity duration-200 disabled:opacity-30 z-10"
        >
          <Scale size={14} />
        </button>
      )}
    </div>
  );
}

function ProductRail({ title, action, products, onOpen, onToggleCompare, compareIds, onNavAction }) {
  const ref = useRef(null);
  const scroll = (dir) => ref.current?.scrollBy({ left: dir * 300, behavior: "smooth" });
  return (
    <section className="max-w-7xl mx-auto px-6 md:px-10 py-16 md:py-32">
      <SectionHeading title={title} action={action} onAction={onNavAction} />
      {products.length ? (
        <div className="relative">
          <div ref={ref} className="flex gap-6 md:gap-8 overflow-x-auto pb-2 scroll-smooth" style={{ scrollbarWidth: "none" }}>
            {products.map((p) => (
              <div key={p.id} className="w-56 md:w-64 shrink-0">
                <ProductCard
                  product={p} onOpen={onOpen}
                  onToggleCompare={onToggleCompare}
                  isComparing={compareIds.includes(p.id)}
                  compareDisabled={compareIds.length >= 3}
                />
              </div>
            ))}
          </div>
          <div className="hidden md:flex justify-end gap-2 mt-6">
            <button onClick={() => scroll(-1)} style={{ borderColor: T.line, color: T.ink }} className="w-9 h-9 rounded-full border flex items-center justify-center hover:border-black transition-colors"><ChevronLeft size={16} /></button>
            <button onClick={() => scroll(1)} style={{ borderColor: T.line, color: T.ink }} className="w-9 h-9 rounded-full border flex items-center justify-center hover:border-black transition-colors"><ChevronRight size={16} /></button>
          </div>
        </div>
      ) : (
        <div style={{ borderColor: T.line, backgroundColor: T.stone }} className="border px-6 py-12 text-center">
          <p style={{ color: T.ink }} className="text-base font-medium">New arrivals coming soon</p>
          <p style={{ color: T.graphite }} className="text-sm mt-2">We're getting something special ready for you.</p>
        </div>
      )}
    </section>
  );
}

/* ============================================================
   NAVBAR
   ============================================================ */
function AnnouncementBar({ go }) {
  const { siteContent } = useStoreData();
  const a = siteContent.announcement;
  if (!a.visible || !a.text) return null;
  const clickable = !!a.link;
  const Comp = clickable ? "button" : "div";
  return (
    <Comp
      onClick={clickable ? () => go("catalog", { category: a.link }) : undefined}
      style={{ backgroundColor: T.ink, color: "#fff" }}
      className={`w-full text-center text-xs md:text-[13px] font-medium py-2.5 px-4 ${clickable ? "hover:opacity-90 cursor-pointer" : ""}`}
    >
      {a.text}
    </Comp>
  );
}

function Navbar({ go, cartCount, compareCount, onSearch, onCart }) {
  const { categories: CATEGORIES } = useStoreData();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <>
      <header
        style={{
          backgroundColor: scrolled ? "rgba(250,250,248,0.86)" : T.paper,
          borderColor: scrolled ? T.line : "transparent",
          backdropFilter: scrolled ? "blur(10px)" : "none",
        }}
        className="sticky top-0 z-40 border-b transition-colors duration-300"
      >
        <div style={{ height: "3.9rem" }} className="max-w-7xl mx-auto px-6 md:px-10 flex items-center justify-between">
          <button onClick={() => go("home")} className="flex items-center gap-2.5 shrink-0">
            <BrandMark size={34} />
            <span style={{ color: T.ink, fontSize: "15px" }} className="font-semibold tracking-tight">Go iPhone</span>
          </button>

          <nav className="hidden md:flex items-center gap-9">
            {CATEGORIES.filter((c) => c.key !== "apple-accessory" && c.key !== "other-accessory").map((c) => (
              <button key={c.key} onClick={() => go("catalog", { category: c.key })}
                style={{ color: T.ink, fontSize: "13.5px" }} className="group relative font-medium py-1">
                {c.label}
                <span className="absolute left-0 -bottom-0 h-px w-0 group-hover:w-full transition-all duration-300" style={{ backgroundColor: T.ink }} />
              </button>
            ))}
            <div className="relative group/acc">
              <button onClick={() => go("catalog", { category: "apple-accessory" })}
                style={{ color: T.ink, fontSize: "13.5px" }} className="group relative font-medium py-1 inline-flex items-center gap-1">
                Accessories
                <ChevronDown size={12} className="transition-transform duration-200 group-hover/acc:rotate-180" style={{ color: T.graphite }} />
                <span className="absolute left-0 -bottom-0 h-px w-0 group-hover:w-full transition-all duration-300" style={{ backgroundColor: T.ink }} />
              </button>
              <div className="absolute left-0 top-full pt-2 opacity-0 invisible translate-y-1 group-hover/acc:opacity-100 group-hover/acc:visible group-hover/acc:translate-y-0 transition-all duration-150 z-20">
                <div style={{ backgroundColor: T.paper, borderColor: T.line }} className="border shadow-sm min-w-[188px] py-1.5">
                  <button onClick={() => go("catalog", { category: "apple-accessory" })}
                    style={{ color: T.ink }} className="block w-full text-left px-4 py-2.5 text-[13.5px] hover:bg-black/[0.03] transition-colors">
                    Apple Accessories
                  </button>
                  <button onClick={() => go("catalog", { category: "other-accessory" })}
                    style={{ color: T.ink }} className="block w-full text-left px-4 py-2.5 text-[13.5px] hover:bg-black/[0.03] transition-colors">
                    Other Accessories
                  </button>
                </div>
              </div>
            </div>
          </nav>

          <div className="flex items-center gap-1 md:gap-2">
            <button onClick={onSearch} aria-label="Search" style={{ color: T.ink }} className="p-2 -m-1"><Search size={19} /></button>
            <button onClick={() => go("compare")} aria-label="Compare" className="relative hidden md:inline-flex p-2 -m-1" style={{ color: T.ink }}>
              <Scale size={19} />
              {compareCount > 0 && (
                <span style={{ backgroundColor: T.ink, fontSize: "10px" }} className="absolute top-0.5 right-0.5 text-white w-4 h-4 rounded-full flex items-center justify-center">{compareCount}</span>
              )}
            </button>
            <button onClick={onCart} aria-label="Cart" className="relative p-2 -m-1" style={{ color: T.ink }}>
              <ShoppingBag size={19} />
              {cartCount > 0 && (
                <span style={{ backgroundColor: T.ink, fontSize: "10px" }} className="absolute top-0.5 right-0.5 text-white w-4 h-4 rounded-full flex items-center justify-center">{cartCount}</span>
              )}
            </button>
            <button onClick={() => setMenuOpen(true)} className="md:hidden p-2 -m-1" aria-label="Menu" style={{ color: T.ink }}><Menu size={21} /></button>
          </div>
        </div>
      </header>

      {menuOpen && (
        <div style={{ backgroundColor: T.paper }} className="fixed inset-0 z-50 md:hidden flex flex-col">
          <div className="flex items-center justify-between px-6" style={{ height: "3.9rem", borderBottom: `1px solid ${T.line}` }}>
            <div className="flex items-center gap-2.5"><BrandMark size={32} /><span style={{ color: T.ink }} className="font-semibold tracking-tight">Go iPhone</span></div>
            <button onClick={() => setMenuOpen(false)} style={{ color: T.ink }} className="p-2 -m-2"><X size={22} /></button>
          </div>
          <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col">
            {CATEGORIES.filter((c) => c.key !== "apple-accessory" && c.key !== "other-accessory").map((c) => (
              <button key={c.key} onClick={() => { go("catalog", { category: c.key }); setMenuOpen(false); }}
                style={{ color: T.ink, borderColor: T.line }} className="text-2xl font-medium tracking-tight py-4 border-b text-left">
                {c.label}
              </button>
            ))}
            <div style={{ borderColor: T.line }} className="border-b py-4">
              <p style={{ color: T.ink }} className="text-2xl font-medium tracking-tight mb-3">Accessories</p>
              <div className="flex flex-col gap-3 pl-0.5">
                <button onClick={() => { go("catalog", { category: "apple-accessory" }); setMenuOpen(false); }}
                  style={{ color: T.graphite }} className="text-sm font-medium text-left">Apple Accessories</button>
                <button onClick={() => { go("catalog", { category: "other-accessory" }); setMenuOpen(false); }}
                  style={{ color: T.graphite }} className="text-sm font-medium text-left">Other Accessories</button>
              </div>
            </div>
            <button onClick={() => { go("compare"); setMenuOpen(false); }} style={{ color: T.graphite, borderColor: T.line }} className="text-sm font-medium py-4 border-b text-left flex items-center justify-between">Compare devices <Scale size={15} /></button>
            <button onClick={() => { go("recommend"); setMenuOpen(false); }} style={{ color: T.graphite }} className="text-sm font-medium py-4 text-left">Find your perfect device</button>
          </div>
        </div>
      )}
    </>
  );
}

/* ============================================================
   SEARCH OVERLAY
   ============================================================ */
function SearchOverlay({ onClose, go }) {
  const { products } = useStoreData();
  const [q, setQ] = useState("");
  const results = useMemo(() => {
    if (!q.trim()) return [];
    const s = q.toLowerCase();
    return products.filter((p) => isPublished(p) &&
      (p.name.toLowerCase().includes(s) ||
      categoryLabel(p.category).toLowerCase().includes(s) ||
      (p.colors || []).some((c) => c.toLowerCase().includes(s)))
    ).slice(0, 8);
  }, [q, products]);
  return (
    <div style={{ backgroundColor: "rgba(18,18,16,0.5)" }} className="fixed inset-0 z-50 flex items-start justify-center pt-24 px-6" onClick={onClose}>
      <div style={{ backgroundColor: T.paper, borderColor: T.line }} className="w-full max-w-xl border overflow-hidden" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center gap-3 px-5 h-14" style={{ borderBottom: `1px solid ${T.line}` }}>
          <Search size={18} style={{ color: T.graphite }} />
          <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search iPhone, iPad, Mac…"
            style={{ color: T.ink }} className="flex-1 bg-transparent outline-none text-base" />
          <button onClick={onClose} style={{ color: T.graphite }} className="p-2 -m-2"><X size={18} /></button>
        </div>
        {results.length > 0 && (
          <div className="max-h-80 overflow-y-auto">
            {results.map((p) => (
              <button key={p.id} onClick={() => { go("product", { id: p.id }); onClose(); }}
                className="w-full flex items-center gap-4 px-5 py-3 hover:bg-white text-left">
                <div style={{ backgroundColor: T.stone }} className="relative w-11 h-11 shrink-0 overflow-hidden">
                  <ProductImage product={p} size={30} />
                </div>
                <div className="min-w-0">
                  <p style={{ color: T.ink }} className="text-sm font-medium truncate">{p.name}</p>
                  <p style={{ color: T.graphite }} className="text-xs">{categoryLabel(p.category)} · {CURRENCY(priceFrom(p) || 0)}</p>
                </div>
              </button>
            ))}
          </div>
        )}
        {q.trim() && results.length === 0 && (
          <div className="px-5 py-10 text-center">
            <Search size={20} style={{ color: T.mist }} className="mx-auto mb-3" />
            <p style={{ color: T.ink }} className="text-sm font-medium">No results for “{q}”</p>
            <p style={{ color: T.graphite }} className="text-xs mt-1">Try a model name, category, or color.</p>
          </div>
        )}
        {!q.trim() && (
          <p style={{ color: T.mist }} className="px-5 py-6 text-xs">Search by model, category, or color.</p>
        )}
      </div>
    </div>
  );
}

/* ============================================================
   HERO
   ============================================================ */
/* SEED_HERO_SLIDES removed — catalog data now comes from the API */

function heroProductFor(products, slide) {
  const pool = products.filter(isPublished);
  return slide.target.view === "product"
    ? products.find((p) => p.id === slide.target.params.id)
    : pool.find((p) => p.category === slide.target.params?.category && hasCollection(p, "featured")) ||
      pool.find((p) => p.category === slide.target.params?.category);
}

function Hero({ go }) {
  const { products, heroSlides: ALL_SLIDES, siteContent } = useStoreData();
  const schedules = siteContent?.heroSlideSchedules || {};
  const now = Date.now();
  const HERO_SLIDES = ALL_SLIDES.filter((s) => {
    const schedule = schedules[s.id] || {};
    return s.active !== false &&
      (!schedule.publishAt || new Date(schedule.publishAt).getTime() <= now) &&
      (!schedule.unpublishAt || new Date(schedule.unpublishAt).getTime() > now);
  });
  const SLIDES = HERO_SLIDES.length ? HERO_SLIDES : [{
    id: "default-hero",
    eyebrow: "GO IPHONE",
    title: "Discover your next favorite.",
    sub: "Explore the latest Apple devices and find the right one for you.",
    cta: "Explore iPhone",
    badge: "",
    active: true,
    duration: 6500,
    image: "",
    mobileImage: "",
    target: { view: "catalog", params: { category: "iphone" } },
  }];
  const [index, setIndex] = useState(0);
  const timerRef = useRef(null);

  useEffect(() => {
    if (SLIDES.length < 2) return;
    const current = SLIDES[Math.min(index, SLIDES.length - 1)];
    timerRef.current = setTimeout(() => {
      setIndex((i) => (i + 1) % SLIDES.length);
    }, current?.duration || 6500);
    return () => clearTimeout(timerRef.current);
  }, [index, SLIDES.length]);

  function goTo(i) {
    setIndex(i);
    clearTimeout(timerRef.current);
  }

  const slide = SLIDES[Math.min(index, SLIDES.length - 1)];
  const secondary = SLIDES[(index + 1) % SLIDES.length];
  if (!slide) return null;

const heroProduct = heroProductFor(products, slide);
  const customImage = slide.image || null;
  const customMobileImage = slide.mobileImage || slide.image || null;

  return (
    <section style={{ backgroundColor: T.ink }} className="relative overflow-hidden min-h-[560px] md:min-h-[640px]">
      {/* Full-bleed image layer — always covers the entire hero, edge to edge */}
      <div key={slide.id} className="hero-fade absolute inset-0">
        {customImage ? (
          <>
            <img src={customMobileImage} alt="" className="md:hidden absolute inset-0 w-full h-full object-cover object-center" />
            <img src={customImage} alt="" className="hidden md:block absolute inset-0 w-full h-full object-cover object-center" />
          </>
        ) : heroProduct ? (
          <ProductImage product={heroProduct} hex="#8E8C86" size={340} />
        ) : (
          <div className="absolute inset-0 flex items-center justify-center">
            <DeviceGlyph category="iphone" hex="#8E8C86" size={340} shadowTint="#FFFFFF" shadowOpacity={0.14} />
          </div>
        )}
      </div>

      {/* Scrim so the overlaid text stays readable over any photo */}
      <div className="absolute inset-0 hidden md:block" style={{ background: "linear-gradient(100deg, rgba(10,10,10,0.88) 0%, rgba(10,10,10,0.62) 38%, rgba(10,10,10,0.18) 65%, rgba(10,10,10,0) 85%)" }} />
      <div className="absolute inset-0 md:hidden" style={{ background: "linear-gradient(0deg, rgba(10,10,10,0.92) 20%, rgba(10,10,10,0.45) 55%, rgba(10,10,10,0.12) 80%)" }} />

      {/* Text layer, overlaid on top of the image */}
      <div className="relative min-h-[560px] md:min-h-[640px] max-w-7xl mx-auto px-6 md:px-10 flex items-end md:items-center">
        <div className="max-w-md py-10 md:py-0">
          <div key={slide.id + "-copy"} className="hero-fade">
            {slide.badge && <span style={{ color: T.brassSoft || "#D4B67A", borderColor: "rgba(255,255,255,0.3)" }} className="inline-block border px-2.5 py-1 text-[11px] font-medium uppercase tracking-wide mb-4">{slide.badge}</span>}
            <p style={{ color: "rgba(255,255,255,0.65)", fontSize: "12.5px", letterSpacing: "0.08em" }} className="mb-5 uppercase">{slide.eyebrow}</p>
            <h1 style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.03em", fontSize: "clamp(2.4rem, 4.6vw, 4rem)", lineHeight: 1.05, textShadow: "0 2px 20px rgba(0,0,0,0.35)" }} className="text-white">
              {slide.title}
            </h1>
            <p className="text-white/75 text-base mt-5 leading-relaxed" style={{ textShadow: "0 1px 12px rgba(0,0,0,0.35)" }}>{slide.sub}</p>
            <div className="flex flex-wrap items-center gap-x-6 gap-y-3 mt-9">
              <button onClick={() => go(slide.target.view, slide.target.params)}
                className="bg-white text-black text-sm font-medium px-7 py-3.5 hover:bg-white/90 transition-colors">
                {slide.cta}
              </button>
              {SLIDES.length > 1 && (
                <button onClick={() => go(secondary.target.view, secondary.target.params)}
                  className="text-white text-sm font-medium hover:text-white/80 transition-colors border-b border-white/40 hover:border-white/70 pb-0.5">
                  {secondary.cta}
                </button>
              )}
            </div>
          </div>

          {SLIDES.length > 1 && (
            <div className="flex items-center gap-2 mt-10">
              {SLIDES.map((s, i) => (
                <button key={s.id} onClick={() => goTo(i)} aria-label={`Go to slide ${i + 1}`}
                  className="h-[3px] transition-all duration-300"
                  style={{ width: i === index ? "26px" : "10px", backgroundColor: i === index ? "#fff" : "rgba(255,255,255,0.4)" }} />
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   CATEGORY GRID
   ============================================================ */
function representativeProduct(categoryKey) {
  const pool = store.products.filter(isPublished);
  return (
    pool.find((p) => p.category === categoryKey && hasCollection(p, "featured")) ||
    pool.find((p) => p.category === categoryKey && hasCollection(p, "best-sellers")) ||
    pool.find((p) => p.category === categoryKey)
  );
}

function CategoryGrid({ go }) {
  const { categories: CATEGORIES, siteContent } = useStoreData();
  const categoryImages = siteContent.categoryImages || {};
  const shown = CATEGORIES.filter((c) => c.key !== "other-accessory");
  // Woven bento pattern: a category spans 2 grid columns, the rest span 1.
  // Because col-span-2 always means "half the row" whether the row has 2
  // columns (mobile) or 4 (desktop), this single set of classes produces a
  // sensible layout at every breakpoint with no responsive span overrides.
  const wide = new Set(["iphone", "apple-accessory"]);

  return (
    <section className="max-w-7xl mx-auto px-6 md:px-10 py-20 md:py-28">
      <SectionHeading title="Shop by category" />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
        {shown.map((c) => {
          const override = categoryImages[c.key];
          const rep = representativeProduct(c.key);
          const hasPhoto = !!override || !!(rep && productImageSrc(rep));
          const isWide = wide.has(c.key);
          return (
            <button key={c.key} onClick={() => go("catalog", { category: c.key })}
              style={{ backgroundColor: T.stone }}
              className={`group relative h-48 md:h-60 flex flex-col justify-between p-5 md:p-6 text-left overflow-hidden ${isWide ? "col-span-2" : "col-span-1"}`}>
              <div className="absolute inset-0 pointer-events-none">
                {override ? (
                  <img src={override} alt="" className="absolute inset-0 w-full h-full object-cover object-center transition-transform duration-300 ease-out group-hover:scale-105" />
                ) : rep ? (
                  <ProductImage product={rep} size={isWide ? 118 : 78} className="transition-transform duration-300 ease-out group-hover:-translate-y-1" imgClassName="transition-transform duration-300 ease-out group-hover:-translate-y-1" />
                ) : (
                  <div className="absolute inset-0 flex items-center justify-center" style={{ padding: isWide ? "0 15%" : "14%" }}>
                    <DeviceGlyph category={c.key === "apple-accessory" ? "pencil" : c.key} hex={DEFAULT_DEVICE_HEX} size={isWide ? 118 : 78} className="transition-transform duration-300 ease-out group-hover:-translate-y-1" />
                  </div>
                )}
              </div>
              <span />
              <span className="relative flex items-center gap-1.5">
                <span style={{ color: hasPhoto ? "#fff" : T.ink, textShadow: hasPhoto ? "0 1px 3px rgba(0,0,0,0.4)" : "none" }} className="text-sm font-medium">{c.label}</span>
                <ChevronRight size={14} style={{ color: hasPhoto ? "#fff" : T.ink }} className="opacity-0 -translate-x-1 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-200" />
              </span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

/* ============================================================
   EDITORIAL FEATURE
   ============================================================ */
function EditorialFeature({ product, go }) {
  if (!product) return null;
  return (
    <section className="max-w-7xl mx-auto px-6 md:px-10 py-16 md:py-24">
      <div className="grid md:grid-cols-[1.3fr_1fr] gap-0 md:gap-16 items-stretch">
        <div style={{ backgroundColor: T.stone }} className="relative order-2 md:order-1 aspect-[4/3] md:aspect-auto overflow-hidden">
          <ProductImage product={product} size={300} />
        </div>
        <div className="order-1 md:order-2 flex flex-col justify-center py-10 md:py-0">
          <p style={{ color: T.graphite, fontSize: "12.5px", letterSpacing: "0.08em" }} className="mb-5 uppercase">Featured</p>
          <h2 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.03em", fontSize: "clamp(2.2rem, 3.4vw, 3.1rem)", lineHeight: 1.06 }} className="mb-5">{product.name}</h2>
          <p style={{ color: T.graphite }} className="text-base max-w-sm mb-8 leading-relaxed">{product.specs.chip} · {product.specs.display}</p>
          <p style={{ color: T.ink, fontVariantNumeric: "tabular-nums", fontWeight: 600 }} className="text-xl mb-9">{CURRENCY(priceFrom(product))}</p>
          <button onClick={() => go("product", { id: product.id })}
            style={{ backgroundColor: T.ink }} className="inline-flex self-start text-white text-sm font-medium px-8 py-4 hover:opacity-90 transition-opacity">
            View {product.name}
          </button>
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   CTA BANNERS (recommendation + compare)
   ============================================================ */
function ToolCard({ icon: Icon, eyebrow, title, description, cta, onClick, image }) {
  return (
    <div className="flex flex-col h-full">
      <div style={{ backgroundColor: T.stone, aspectRatio: "16 / 9" }} className="flex items-center justify-center overflow-hidden">
        {image ? <img src={image} alt="" className="w-full h-full object-cover" /> : <Icon size={40} strokeWidth={1.3} style={{ color: T.graphite }} />}
      </div>
      <div className="pt-7 flex flex-col flex-1">
        <p style={{ color: T.graphite, fontSize: "13px", letterSpacing: "0.02em" }} className="mb-2">{eyebrow}</p>
        <h3 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em", fontSize: "1.6rem", lineHeight: 1.2 }} className="mb-2.5 max-w-sm">{title}</h3>
        <p style={{ color: T.graphite }} className="text-sm leading-relaxed max-w-sm mb-7">{description}</p>
        <button onClick={onClick} style={{ backgroundColor: T.ink }}
          className="mt-auto self-start text-white text-sm font-medium px-6 py-3 hover:opacity-90 transition-opacity">
          {cta}
        </button>
      </div>
    </div>
  );
}

function ToolsSection({ onRecommend, onCompare }) {
  const { siteContent } = useStoreData();
  const rec = siteContent.recommendationSection;
  const cmp = siteContent.comparisonSection;
  const settings = siteContent.toolsSection || {};
  if (settings.visible === false || (rec.visible === false && cmp.visible === false)) return null;
  return (
    <section className="max-w-7xl mx-auto px-6 md:px-10 py-16 md:py-32">
      <SectionHeading eyebrow={settings.eyebrow || "Tools"} title={settings.title || "Not sure which to choose?"} />
      <div className="grid md:grid-cols-2 gap-10 md:gap-14">
        {rec.visible !== false && (
          <ToolCard
            icon={Sparkles}
            image={settings.recommendationImage || rec.image}
            eyebrow="Guided shopping"
            title={rec.title}
            description={rec.description}
            cta={rec.cta}
            onClick={onRecommend}
          />
        )}
        {cmp.visible !== false && (
          <ToolCard
            icon={Scale}
            image={settings.comparisonImage || cmp.image}
            eyebrow="Side by side"
            title={cmp.title}
            description={cmp.description}
            cta={cmp.cta}
            onClick={onCompare}
          />
        )}
      </div>
    </section>
  );
}

/* ============================================================
   TRUST SECTION — reiterates real, existing policies (warranty,
   per-unit battery/condition disclosure, cash on delivery) rather
   than inventing new guarantees. Sits between the tools and the
   footer as a quiet close to the homepage.
   ============================================================ */
function TrustSection() {
  const { siteContent } = useStoreData();
  const settings = siteContent.trustSection || {};
  const defaults = [
    { id: "warranty", icon: ShieldCheck, title: "Every device warrantied", desc: "New and certified pre-owned devices each ship with a Go iPhone warranty." },
    { id: "battery", icon: BatteryMedium, title: "Battery health disclosed", desc: "Pre-owned battery health and condition are graded and shown before you buy." },
    { id: "grading", icon: Check, title: "Individually graded", desc: "Each pre-owned unit is inspected on its own, not sold by a generic condition tier." },
    { id: "delivery", icon: CircleCheck, title: "Cash on delivery", desc: "Pay when your order arrives, anywhere we deliver." },
  ];
  const icons = { warranty: ShieldCheck, battery: BatteryMedium, grading: Check, delivery: CircleCheck };
  const points = defaults.map(base => {
    const saved = (settings.points || []).find(point => point.id === base.id) || {};
    return { ...base, ...saved, icon: icons[base.id] };
  }).filter(point => point.visible !== false);
  if (settings.visible === false || !points.length) return null;
  return (
    <section style={{ borderColor: T.line }} className="max-w-7xl mx-auto px-6 md:px-10 py-20 md:py-24 border-t">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-10">
        {points.map(({ icon: Icon, title, desc, image }) => (
          <div key={title} className="flex flex-col gap-3">
            {image ? <img src={image} alt="" loading="lazy" style={{ width: 34, height: 34, objectFit: "contain" }} /> : <Icon size={18} strokeWidth={1.5} style={{ color: T.graphite }} />}
            <div>
              <p style={{ color: T.ink }} className="text-sm font-medium mb-1">{title}</p>
              <p style={{ color: T.graphite }} className="text-xs leading-relaxed">{desc}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

/* ============================================================
   FOOTER
   ============================================================ */
function Footer({ go }) {
  return (
    <footer style={{ backgroundColor: T.ink }} className="mt-6">
      <div className="max-w-7xl mx-auto px-6 md:px-10 py-20 grid md:grid-cols-4 gap-12 md:gap-10">
        <div>
          <div className="flex items-center gap-2.5 mb-5"><BrandMark size={30} /><span className="text-white font-semibold tracking-tight">Go iPhone</span></div>
          <p className="text-white/45 text-sm max-w-xs leading-relaxed">A premium independent retailer for Apple devices — new and certified pre-owned.</p>
        </div>
        <div>
          <p className="text-white/70 text-xs font-medium tracking-wide mb-4">Shop</p>
          <div className="flex flex-col gap-3">
            {["iphone", "ipad", "mac", "watch", "airpods"].map((k) => (
              <button key={k} onClick={() => go("catalog", { category: k })} className="text-white/50 text-sm text-left hover:text-white transition-colors">{categoryLabel(k)}</button>
            ))}
          </div>
        </div>
        <div>
          <p className="text-white/70 text-xs font-medium tracking-wide mb-4">Tools</p>
          <div className="flex flex-col gap-3">
            <button onClick={() => go("recommend")} className="text-white/50 text-sm text-left hover:text-white transition-colors">Find your perfect device</button>
            <button onClick={() => go("compare")} className="text-white/50 text-sm text-left hover:text-white transition-colors">Compare devices</button>
          </div>
        </div>
        <div>
          <p className="text-white/70 text-xs font-medium tracking-wide mb-4">Store</p>
          <p className="text-white/50 text-sm">Alexandria, Egypt</p>
          <p className="text-white/50 text-sm mt-1.5">Cash on delivery available</p>
        </div>
      </div>
      <div style={{ borderColor: "rgba(255,255,255,0.1)" }} className="border-t px-6 md:px-10 py-6 flex items-center justify-between gap-4">
        <p className="text-white/30 text-xs">© {new Date().getFullYear()} Go iPhone. Not affiliated with Apple Inc.</p>
      </div>
    </footer>
  );
}

/* ============================================================
   COMPARE TRAY (persistent bottom bar)
   ============================================================ */
function CompareTray({ compareIds, onClear, go }) {
  if (!compareIds.length) return null;
  return (
    <div style={{ backgroundColor: T.ink, borderColor: "rgba(255,255,255,0.1)" }} className="fixed bottom-0 left-0 right-0 z-30 border-t">
      <div className="max-w-7xl mx-auto px-4 md:px-10 h-16 flex items-center justify-between gap-3">
        <div className="flex items-center gap-2 md:gap-3 min-w-0">
          <Scale size={16} className="text-white/70 shrink-0" />
          <span className="text-white text-sm truncate">{compareIds.length} selected</span>
        </div>
        <div className="flex items-center gap-3 md:gap-4 shrink-0">
          <button onClick={onClear} className="hidden sm:inline text-white/50 text-sm hover:text-white">Clear all</button>
          <button onClick={() => go("compare")} style={{ backgroundColor: "#fff", color: T.ink }} className="text-sm font-medium px-4 md:px-5 py-2.5 whitespace-nowrap">Compare now</button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   HOME PAGE
   ============================================================ */
/* ============================================================
   BEST SELLERS — a real grid, distinct from the Latest Arrivals
   horizontal rail, so the two sections don't read as the same
   component twice.
   ============================================================ */
function ProductGrid({ title, action, products, onOpen, onToggleCompare, compareIds, onNavAction }) {
  return (
    <section className="max-w-7xl mx-auto px-6 md:px-10 py-20 md:py-28">
      <SectionHeading title={title} action={action} onAction={onNavAction} />
      {products.length ? (
        <div className="grid grid-cols-2 md:grid-cols-3 gap-x-6 gap-y-12 md:gap-x-8 md:gap-y-16">
          {products.map((p) => (
            <ProductCard key={p.id} product={p} onOpen={onOpen} onToggleCompare={onToggleCompare}
              isComparing={compareIds.includes(p.id)} compareDisabled={compareIds.length >= 3} />
          ))}
        </div>
      ) : (
        <div style={{ borderColor: T.line, backgroundColor: T.stone }} className="border px-6 py-12 text-center">
          <p style={{ color: T.ink }} className="text-base font-medium">Our best sellers will be here soon</p>
          <p style={{ color: T.graphite }} className="text-sm mt-2">Check back soon to discover our most-loved devices.</p>
        </div>
      )}
    </section>
  );
}
/* ============================================================
   CERTIFIED PRE-OWNED — an intro column + product grid, so this
   reads as its own trust-building composition rather than a third
   copy of the best-seller / latest-arrivals pattern.
   ============================================================ */
function CertifiedPreownedSection({ products, go, onOpen, onToggleCompare, compareIds }) {
  return (
    <section style={{ backgroundColor: T.stone }} className="py-20 md:py-28">
      <div className="max-w-7xl mx-auto px-6 md:px-10 grid md:grid-cols-[0.85fr_1.4fr] gap-10 md:gap-16">
        <div>
          <p style={{ color: T.graphite, fontSize: "12.5px", letterSpacing: "0.08em" }} className="mb-5 uppercase">Certified pre-owned</p>
          <h2 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em", fontSize: "clamp(1.9rem, 2.6vw, 2.5rem)", lineHeight: 1.14 }} className="mb-5 max-w-xs">
            Carefully checked. Clearly graded. Honestly priced.
          </h2>
          <p style={{ color: T.graphite }} className="text-sm leading-relaxed max-w-xs mb-8">
            Every unit is individually inspected — battery health, cosmetic condition, and storage are disclosed upfront, backed by a Go iPhone warranty.
          </p>
          <button onClick={() => go("catalog", { category: "iphone" })}
            style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5 hover:opacity-90 transition-opacity">
            Browse certified pre-owned
          </button>
        </div>
        {products.length ? (
          <div className="grid grid-cols-2 gap-5 md:gap-6">
            {products.map((p) => (
              <ProductCard key={p.id} product={p} onOpen={onOpen} onToggleCompare={onToggleCompare}
                isComparing={compareIds.includes(p.id)} compareDisabled={compareIds.length >= 3} />
            ))}
          </div>
        ) : (
          <div className="flex items-center justify-center border border-dashed px-6 py-12 text-center" style={{ borderColor: T.line }}>
            <div>
              <p style={{ color: T.ink }} className="text-base font-medium">Certified pre-owned devices coming soon</p>
              <p style={{ color: T.graphite }} className="text-sm mt-2">Quality-checked devices will be listed here soon.</p>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

function HomePage({ go, compareIds, onToggleCompare }) {
  const { products: allProducts, siteContent } = useStoreData();
  const PRODUCTS = allProducts.filter(isPublished);
  const collectionSettings = siteContent.collections || [];
  const preowned = PRODUCTS.filter((p) => p.hasUnits);
  const featured = PRODUCTS.find((p) => hasCollection(p, "featured") && p.category === "iphone");
  const merchandisingSections = collectionSettings
    .filter((c) => c.visible !== false)
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
    .map((c) => ({
      ...c,
      products: c.id === "featured"
        ? (featured ? [featured] : [])
        : c.id === "certified-refurbished"
          ? preowned
          : PRODUCTS.filter((p) => hasCollection(p, c.id)),
    }))
    .filter((c) => c.products.length > 0);
  const defaultLayout = [
    { id: "hero", visible: true, order: 0 },
    { id: "categories", visible: true, order: 1 },
    { id: "collections", visible: true, order: 2 },
    { id: "tools", visible: true, order: 3 },
    { id: "trust", visible: true, order: 4 },
  ];
  const savedLayout = Array.isArray(siteContent.homepageLayout) ? siteContent.homepageLayout : [];
  const homepageLayout = (savedLayout.length
    ? savedLayout.map(item => ({ ...item, type: item.type || item.id }))
    : defaultLayout.map(item => ({ ...item, type: item.id }))
  ).sort((a, b) => a.order - b.order);
  const now = Date.now();
  const isInPublishWindow = item =>
    (!item.publishAt || new Date(item.publishAt).getTime() <= now) &&
    (!item.unpublishAt || new Date(item.unpublishAt).getTime() > now);

  function renderCollection(section, index) {
    if (section.id === "featured") return <EditorialFeature key={section.id} product={section.products[0]} go={go} />;
    if (section.id === "certified-refurbished") return <CertifiedPreownedSection key={section.id} products={section.products} go={go} onOpen={(id) => go("product", { id })} onToggleCompare={onToggleCompare} compareIds={compareIds} />;
    const onNavAction = () => go("catalog", { category: section.products[0]?.category || "iphone" });
    const props = { title: section.name, action: "View all", onNavAction, products: section.products, onOpen: (id) => go("product", { id }), onToggleCompare, compareIds };
    if (section.id === "best-sellers") return <ProductGrid key={section.id} {...props} />;
    if (section.id === "new-arrivals") return <ProductRail key={section.id} {...props} />;
    const RailOrGrid = index % 2 === 0 ? ProductRail : ProductGrid;
    return <RailOrGrid key={section.id} {...props} />;
  }

  return (
    <div>
      {homepageLayout.filter(item => item.visible !== false && isInPublishWindow(item)).map(item => {
        const type = item.type || item.id;
        if (type === "hero") return <Hero key={item.id} go={go} />;
        if (type === "categories") return <CategoryGrid key={item.id} go={go} />;
        if (type === "collections") return <React.Fragment key={item.id}>{merchandisingSections.map((section, index) => renderCollection(section, index))}</React.Fragment>;
        if (type === "tools") return <ToolsSection key={item.id} onRecommend={() => go("recommend")} onCompare={() => go("compare")} />;
        if (type === "trust") return <TrustSection key={item.id} />;
        return null;
      })}
    </div>
  );
}

/* ============================================================
   CATALOG PAGE
   ============================================================ */
const CATEGORY_FILTER_KEYS = {
  iphone: ["storage", "color", "condition"],
  ipad: ["storage", "color"],
  mac: ["storage", "color"],
  watch: ["storage", "color"],
  airpods: ["color"],
  "apple-accessory": [],
  "other-accessory": ["color"],
};

function buildFilterOptions(category) {
  const items = store.products.filter((p) => p.category === category && isPublished(p));
  const keys = CATEGORY_FILTER_KEYS[category] || [];
  const options = {};
  keys.forEach((key) => {
    const set = new Set();
    items.forEach((p) => {
      if (key === "storage") (p.storageOptions || []).forEach((v) => set.add(v));
      if (key === "color") (p.colors || []).forEach((v) => set.add(v));
      if (key === "condition") {
        if (p.hasUnits) unitsFor(p.id).forEach((u) => set.add(u.condition));
        else set.add("New");
      }
    });
    options[key] = Array.from(set);
  });
  return options;
}

function CatalogPage({ category, go, compareIds, onToggleCompare }) {
  const { products: allProducts } = useStoreData();
  const [active, setActive] = useState({});
  const [sort, setSort] = useState("relevance");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [filtersMounted, filtersVisible] = useMountTransition(filtersOpen, 260);
  useEffect(() => setActive({}), [category]);

  const options = useMemo(() => buildFilterOptions(category), [category, allProducts]);
  const keys = CATEGORY_FILTER_KEYS[category] || [];

  const items = allProducts.filter((p) => p.category === category && isPublished(p)).filter((p) => {
    return keys.every((key) => {
      const chosen = active[key];
      if (!chosen || !chosen.length) return true;
      if (key === "storage") return (p.storageOptions || []).some((v) => chosen.includes(v));
      if (key === "color") return (p.colors || []).some((v) => chosen.includes(v));
      if (key === "condition") {
        if (p.hasUnits) return unitsFor(p.id).some((u) => chosen.includes(u.condition));
        return chosen.includes("New");
      }
      return true;
    });
  });

  const sorted = [...items].sort((a, b) => {
    const pa = priceFrom(a) || 0, pb = priceFrom(b) || 0;
    if (sort === "price-asc") return pa - pb;
    if (sort === "price-desc") return pb - pa;
    return 0;
  });

  function toggle(key, val) {
    setActive((prev) => {
      const cur = prev[key] || [];
      const next = cur.includes(val) ? cur.filter((v) => v !== val) : [...cur, val];
      return { ...prev, [key]: next };
    });
  }

  const filterLabel = { storage: "Storage", color: "Color", condition: "Condition" };

  return (
    <div className="max-w-7xl mx-auto px-6 md:px-10 py-12">
      <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between mb-8">
        <div>
          <p style={{ color: T.graphite }} className="text-sm mb-1">{items.length} device{items.length !== 1 ? "s" : ""}</p>
          <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em", fontSize: "clamp(1.9rem, 3.2vw, 2.75rem)", lineHeight: 1.12 }}>{categoryLabel(category)}</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setFiltersOpen((v) => !v)} style={{ borderColor: T.line, color: T.ink }} className="md:hidden border px-3 py-2.5 text-sm flex items-center gap-1.5 flex-1 justify-center">
            <SlidersHorizontal size={14} /> Filters
          </button>
          <select value={sort} onChange={(e) => setSort(e.target.value)} style={{ borderColor: T.line, color: T.ink }} className="border px-3 py-2.5 md:py-2 text-sm bg-transparent flex-1 md:flex-none">
            <option value="relevance">Relevance</option>
            <option value="price-asc">Price: low to high</option>
            <option value="price-desc">Price: high to low</option>
          </select>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-10">
        {keys.length > 0 && (
          <aside className="hidden md:block md:w-56 shrink-0">
            <div className="flex flex-col gap-7">
              {keys.map((key) => (
                <div key={key}>
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-3">{filterLabel[key]}</p>
                  <div className="flex flex-col gap-2">
                    {options[key].map((val) => (
                      <label key={val} className="flex items-center gap-2 cursor-pointer">
                        <span
                          onClick={() => toggle(key, val)}
                          style={{ borderColor: (active[key] || []).includes(val) ? T.ink : T.line, backgroundColor: (active[key] || []).includes(val) ? T.ink : "transparent" }}
                          className="w-4 h-4 border flex items-center justify-center shrink-0"
                        >
                          {(active[key] || []).includes(val) && <Check size={11} color="#fff" />}
                        </span>
                        <span style={{ color: T.graphite }} className="text-sm">{val}</span>
                      </label>
                    ))}
                  </div>
                </div>
              ))}
              {Object.values(active).some((v) => v && v.length) && (
                <button onClick={() => setActive({})} style={{ color: T.ink }} className="text-sm text-left font-medium underline underline-offset-4">Clear filters</button>
              )}
            </div>
          </aside>
        )}

        {keys.length > 0 && filtersMounted && (
          <div className="fixed inset-0 z-50 flex items-end md:hidden">
            <div
              style={{ backgroundColor: "rgba(18,18,16,0.45)", opacity: filtersVisible ? 1 : 0, transition: "opacity 250ms ease" }}
              className="absolute inset-0" onClick={() => setFiltersOpen(false)}
            />
            <div
              style={{
                backgroundColor: T.paper,
                transform: filtersVisible ? "translateY(0)" : "translateY(100%)",
                transition: "transform 280ms cubic-bezier(0.22, 1, 0.36, 1)",
              }}
              className="relative w-full max-h-[80vh] flex flex-col rounded-t-2xl overflow-hidden"
            >
              <div className="flex items-center justify-between px-6 h-14 shrink-0" style={{ borderBottom: `1px solid ${T.line}` }}>
                <h2 style={{ color: T.ink }} className="text-base font-semibold">Filters</h2>
                <button onClick={() => setFiltersOpen(false)} style={{ color: T.ink }} aria-label="Close filters" className="p-2 -m-2"><X size={20} /></button>
              </div>
              <div className="flex-1 overflow-y-auto px-6 py-6 flex flex-col gap-7">
                {keys.map((key) => (
                  <div key={key}>
                    <p style={{ color: T.ink }} className="text-sm font-medium mb-3">{filterLabel[key]}</p>
                    <div className="flex flex-wrap gap-2">
                      {options[key].map((val) => {
                        const activeVal = (active[key] || []).includes(val);
                        return (
                          <button key={val} onClick={() => toggle(key, val)}
                            style={{ borderColor: activeVal ? T.ink : T.line, backgroundColor: activeVal ? T.ink : "transparent", color: activeVal ? "#fff" : T.ink }}
                            className="border px-3.5 py-2 text-sm font-medium">
                            {val}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
              <div className="shrink-0 px-6 py-4 flex items-center gap-3" style={{ borderTop: `1px solid ${T.line}` }}>
                {Object.values(active).some((v) => v && v.length) && (
                  <button onClick={() => setActive({})} style={{ borderColor: T.line, color: T.ink }} className="border px-5 py-3 text-sm font-medium">Clear</button>
                )}
                <button onClick={() => setFiltersOpen(false)} style={{ backgroundColor: T.ink }} className="flex-1 text-white text-sm font-medium py-3">
                  Show {sorted.length} device{sorted.length !== 1 ? "s" : ""}
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="flex-1 min-w-0">
          {sorted.length === 0 ? (
            <p style={{ color: T.graphite }} className="text-sm py-16 text-center">No devices match these filters.</p>
          ) : (
            <div className="grid grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-10 md:gap-x-8 md:gap-y-14">
              {sorted.map((p) => (
                <ProductCard key={p.id} product={p} onOpen={(id) => go("product", { id })}
                  onToggleCompare={onToggleCompare} isComparing={compareIds.includes(p.id)} compareDisabled={compareIds.length >= 3} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   PRODUCT DETAIL PAGE
   ============================================================ */
function BatteryBar({ pct }) {
  const color = pct >= 90 ? T.ok : pct >= 80 ? T.brassDeep : T.graphite;
  return (
    <div className="flex items-center gap-2">
      <div style={{ backgroundColor: T.stoneDeep }} className="w-16 h-1.5 rounded-full overflow-hidden">
        <div style={{ width: `${pct}%`, backgroundColor: color }} className="h-full rounded-full" />
      </div>
      <span style={{ color }} className="text-xs font-medium">{pct}%</span>
    </div>
  );
}

function ProductDetailPage({ productId, go, onAddToCart, compareIds, onToggleCompare }) {
  const { products: allProducts, addReservation } = useStoreData();
  const product = allProducts.find((p) => p.id === productId);
  const [selectedUnit, setSelectedUnit] = useState(null);
  const [storage, setStorage] = useState(null);
  const [color, setColor] = useState(null);
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);
  const [reserveOpen, setReserveOpen] = useState(false);
  const [reserveForm, setReserveForm] = useState({ name: "", phone: "", email: "", notes: "" });
  const [reserveSubmitted, setReserveSubmitted] = useState(false);
  const [reserving, setReserving] = useState(false);
  const [reserveError, setReserveError] = useState("");

  useEffect(() => {
    setAdded(false);
    setReserveOpen(false);
    setReserveSubmitted(false);
    if (product?.hasUnits) {
      const units = unitsFor(product.id);
      setSelectedUnit(units[0] || null);
    } else if (product) {
      setStorage(product.storageOptions?.[0] || "Standard");
      setColor(product.colors?.[0] || null);
    }
    setQty(1);
  }, [productId]); // eslint-disable-line

  if (!product) {
    return <div className="max-w-3xl mx-auto px-6 py-24 text-center"><p style={{ color: T.graphite }}>Device not found.</p></div>;
  }

  const price = product.hasUnits ? selectedUnit?.price : product.variantPricing?.[storage];
  const comparable = !["apple-accessory", "other-accessory"].includes(product.category);
  const salesMode = getSalesMode(product);
  const isReservation = salesMode === "reservation";
  const reservationCfg = product.reservation || { ctaText: "Reserve now", message: "", expectedDate: product.launchDate || "", depositRequired: false, isRequestOnly: true };

  function handleAdd() {
    if (product.hasUnits && selectedUnit) {
      onAddToCart({
        key: selectedUnit.id, productId: product.id, name: product.name, category: product.category,
        variantLabel: `${selectedUnit.storage} · ${selectedUnit.color} · ${selectedUnit.condition}`,
        unitId: selectedUnit.id, unitPrice: selectedUnit.price, qty: 1, maxQty: 1, isPreorder: false,
      });
    } else {
      onAddToCart({
        key: `${product.id}-${storage}-${color}`, productId: product.id, name: product.name, category: product.category,
        variantLabel: [storage !== "Standard" ? storage : null, color].filter(Boolean).join(" · "),
        storage: storage === "Standard" ? null : storage, color,
        unitPrice: price, qty, maxQty: 99, isPreorder: false,
      });
    }
    setAdded(true);
  }

  async function handleReserveSubmit(e) {
    e.preventDefault();
    if (!reserveForm.name.trim() || !reserveForm.phone.trim() || reserving) return;
    setReserving(true);
    setReserveError("");
    try {
      await addReservation({
        productId: product.id, name: reserveForm.name.trim(), phone: reserveForm.phone.trim(),
        email: reserveForm.email.trim() || null, storage, color, qty, notes: reserveForm.notes.trim() || null,
      });
      setReserveSubmitted(true);
    } catch (err) {
      setReserveError(err.message);
    } finally {
      setReserving(false);
    }
  }

  return (
    <div className="max-w-7xl mx-auto px-6 md:px-10 py-14 md:py-16">
      <button onClick={() => go("catalog", { category: product.category })} style={{ color: T.graphite }} className="text-sm mb-10 inline-flex items-center gap-1"><ChevronLeft size={14} /> {categoryLabel(product.category)}</button>

      <div className="grid md:grid-cols-[3fr_2fr] gap-16 md:gap-24 items-start">
        <div className="md:sticky md:top-24 w-full flex flex-col gap-3">
          <div style={{ backgroundColor: T.stone }} className="relative aspect-square md:aspect-[4/5] overflow-hidden">
            <ProductImage product={product} hex={SWATCH[selectedUnit?.color] || SWATCH[color] || DEFAULT_DEVICE_HEX} size={340} />
          </div>
          {productGallery(product).length > 1 && (
            <div className="flex gap-2.5">
              {productGallery(product).map((src, i) => (
                <div key={src + i} style={{ backgroundColor: T.stone, borderColor: T.line }} className="relative w-16 h-16 border overflow-hidden">
                  <img src={src} alt="" className="absolute inset-0 w-full h-full object-cover object-center" />
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="md:pt-4">
          {(isReservation || product.hasUnits || (product.badges || []).length > 0) && (
            <div className="flex flex-wrap items-center gap-2 mb-3">
              {isReservation && <Badge tone="brass">{reservationCfg.expectedDate ? `Pre-order · ${reservationCfg.expectedDate}` : "Pre-order"}</Badge>}
              {product.hasUnits && <Badge>Certified pre-owned</Badge>}
              {(product.badges || []).map((b) => <Badge key={b} tone="neutral">{b}</Badge>)}
            </div>
          )}
          <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.025em", fontSize: "clamp(1.9rem, 3.2vw, 2.75rem)", lineHeight: 1.1 }} className="mb-2.5">{product.name}</h1>
          <p style={{ color: T.graphite, fontSize: "15px" }} className="mb-7 leading-relaxed">{product.tagline}</p>

          {price != null && (
            <p style={{ color: T.ink, fontVariantNumeric: "tabular-nums", fontWeight: 700, letterSpacing: "-0.01em", fontSize: "28px" }} className="mb-8">{CURRENCY(price)}</p>
          )}

          {product.hasUnits ? (
            <div className="mb-8">
              <p style={{ color: T.ink }} className="text-sm font-medium mb-3">Choose your device</p>
              <div className="flex flex-col gap-3">
                {unitsFor(product.id).map((u) => {
                  const sel = selectedUnit?.id === u.id;
                  return (
                    <button key={u.id} onClick={() => setSelectedUnit(u)}
                      style={{ borderColor: sel ? T.ink : T.line, backgroundColor: sel ? T.stone : "transparent" }}
                      className="border p-4 flex items-start gap-4 text-left transition-colors">
                      <div style={{ backgroundColor: sel ? "rgba(255,255,255,0.6)" : T.stone }} className="relative w-14 h-14 shrink-0 overflow-hidden">
                        <ProductImage product={product} hex={SWATCH[u.color] || DEFAULT_DEVICE_HEX} size={40} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-3">
                          <p style={{ color: T.ink }} className="text-sm font-medium">{u.storage} · {u.color}</p>
                          <span style={{ color: T.ink, fontVariantNumeric: "tabular-nums" }} className="text-sm font-semibold shrink-0">{CURRENCY(u.price)}</span>
                        </div>
                        <div className="flex items-center gap-3 mt-2">
                          <BatteryBar pct={u.battery} />
                          <span style={{ color: conditionTone(u.condition) }} className="text-xs font-medium">{u.condition}</span>
                        </div>
                        <p style={{ color: T.mist }} className="text-xs mt-2 flex items-center gap-1.5">
                          <ShieldCheck size={12} /> {u.warranty}
                          {sel && <CircleCheck size={13} style={{ color: T.ink }} className="ml-auto shrink-0" />}
                        </p>
                      </div>
                    </button>
                  );
                })}
              </div>
              <p style={{ color: T.mist }} className="text-xs mt-3">Each unit is a unique item — once sold it's removed from inventory.</p>
            </div>
          ) : (
            <div className="mb-8 flex flex-col gap-6">
              {product.storageOptions && (
                <div>
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-3">Storage</p>
                  <div className="flex flex-wrap gap-2">
                    {product.storageOptions.map((s) => (
                      <button key={s} onClick={() => setStorage(s)}
                        style={{ borderColor: storage === s ? T.ink : T.line, backgroundColor: storage === s ? T.ink : "transparent", color: storage === s ? "#fff" : T.ink }}
                        className="border px-4 py-2 text-sm font-medium">
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              )}
              {product.colors && (
                <div>
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-3">Color — {color}</p>
                  <div className="flex flex-wrap gap-2.5">
                    {product.colors.map((c) => (
                      <button key={c} onClick={() => setColor(c)} title={c}
                        style={{ backgroundColor: SWATCH[c] || "#ccc", borderColor: color === c ? T.ink : "transparent", boxShadow: color === c ? `0 0 0 1px ${T.ink}` : "none" }}
                        className="w-8 h-8 rounded-full border-2" />
                    ))}
                  </div>
                </div>
              )}
              {!product.hasUnits && (
                <div>
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-3">Quantity</p>
                  <div style={{ borderColor: T.line }} className="inline-flex items-center border">
                    <button onClick={() => setQty((v) => Math.max(1, v - 1))} className="px-3 py-2"><Minus size={14} /></button>
                    <span className="px-4 text-sm font-medium">{qty}</span>
                    <button onClick={() => setQty((v) => v + 1)} className="px-3 py-2"><Plus size={14} /></button>
                  </div>
                </div>
              )}
            </div>
          )}

          {isReservation ? (
            <div className="mb-3">
              {reservationCfg.message && <p style={{ color: T.graphite }} className="text-sm mb-4">{reservationCfg.message}</p>}
              {!reserveOpen ? (
                <div className="flex items-center gap-3">
                  <button onClick={() => setReserveOpen(true)} style={{ backgroundColor: T.ink }} className="flex-1 text-white text-sm font-medium py-3.5 hover:opacity-90 transition-opacity">
                    {reservationCfg.ctaText || "Reserve now"}
                  </button>
                  {comparable && (
                    <button onClick={() => onToggleCompare(product.id)}
                      style={{ borderColor: compareIds.includes(product.id) ? T.ink : T.line, color: T.ink }}
                      className="border px-4 py-3.5" title="Add to compare">
                      <Scale size={17} />
                    </button>
                  )}
                </div>
              ) : reserveSubmitted ? (
                <div style={{ borderColor: T.line, backgroundColor: T.stone }} className="border p-5">
                  <p style={{ color: T.ink }} className="text-sm font-medium flex items-center gap-2"><Check size={15} style={{ color: T.ok }} /> Request received</p>
                  <p style={{ color: T.graphite }} className="text-sm mt-1.5">We'll contact you at {reserveForm.phone} to confirm your reservation.</p>
                </div>
              ) : (
                <form onSubmit={handleReserveSubmit} style={{ borderColor: T.line }} className="border p-5 flex flex-col gap-3">
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-1">Request this product</p>
                  <input required placeholder="Full name" value={reserveForm.name} onChange={(e) => setReserveForm({ ...reserveForm, name: e.target.value })}
                    style={{ borderColor: T.line }} className="border px-3 py-2.5 text-sm bg-transparent" />
                  <input required placeholder="Phone number" value={reserveForm.phone} onChange={(e) => setReserveForm({ ...reserveForm, phone: e.target.value })}
                    style={{ borderColor: T.line }} className="border px-3 py-2.5 text-sm bg-transparent" />
                  <input type="email" placeholder="Email (optional)" value={reserveForm.email} onChange={(e) => setReserveForm({ ...reserveForm, email: e.target.value })}
                    style={{ borderColor: T.line }} className="border px-3 py-2.5 text-sm bg-transparent" />
                  <textarea placeholder="Notes (optional)" value={reserveForm.notes} onChange={(e) => setReserveForm({ ...reserveForm, notes: e.target.value })}
                    style={{ borderColor: T.line }} rows={2} className="border px-3 py-2.5 text-sm bg-transparent resize-none" />
                  {reserveError && <p style={{ color: "#B3261E" }} className="text-sm">{reserveError}</p>}
                  {reservationCfg.depositRequired && <p style={{ color: T.graphite }} className="text-xs">A deposit will be requested once we confirm availability.</p>}
                  <div className="flex items-center gap-3 mt-1">
                    <button type="submit" disabled={reserving} style={{ backgroundColor: T.ink }} className="flex-1 text-white text-sm font-medium py-3 disabled:opacity-50">{reserving ? "Sending…" : "Submit request"}</button>
                    <button type="button" onClick={() => setReserveOpen(false)} style={{ color: T.graphite }} className="text-sm">Cancel</button>
                  </div>
                </form>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-3 mb-3">
              <button onClick={handleAdd} style={{ backgroundColor: T.ink }} className="flex-1 text-white text-sm font-medium py-3.5 hover:opacity-90 transition-opacity">
                Add to cart
              </button>
              {comparable && (
                <button onClick={() => onToggleCompare(product.id)}
                  style={{ borderColor: compareIds.includes(product.id) ? T.ink : T.line, color: T.ink }}
                  className="border px-4 py-3.5" title="Add to compare">
                  <Scale size={17} />
                </button>
              )}
            </div>
          )}
          {added && <p style={{ color: T.ok }} className="text-sm flex items-center gap-1.5"><Check size={14} /> Added — <button onClick={() => go("cart")} className="underline">view cart</button></p>}

          <div style={{ borderColor: T.line }} className="border-t mt-8 pt-6 flex flex-col gap-2">
            <p style={{ color: T.graphite }} className="text-sm flex items-center gap-2"><ShieldCheck size={15} /> {product.hasUnits ? selectedUnit?.warranty : "12-month Go iPhone warranty"}</p>
            <p style={{ color: T.graphite }} className="text-sm flex items-center gap-2"><BatteryMedium size={15} /> {product.hasUnits ? `Battery health ${selectedUnit?.battery}%` : "100% battery health, sealed unit"}</p>
          </div>
        </div>
      </div>

      <div className="mt-20">
        <h2 style={{ color: T.ink }} className="text-xl font-semibold mb-6">Specifications</h2>
        <div style={{ borderColor: T.line }} className="border divide-y" >
          {Object.entries(product.specs).map(([k, v]) => (
            <div key={k} style={{ borderColor: T.line }} className="grid grid-cols-1 sm:grid-cols-3 gap-1 sm:gap-0 px-5 py-3.5 text-sm">
              <span style={{ color: T.graphite }} className="capitalize sm:col-span-1">{k.replace(/([A-Z])/g, " $1")}</span>
              <span style={{ color: T.ink }} className="sm:col-span-2">{v}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   COMPARE PAGE
   ============================================================ */
const COMPARE_GROUPS = [
  { title: "Overview", rows: [
    { key: "price", label: "Price" },
    { key: "condition", label: "Condition" },
  ] },
  { title: "Design", rows: [
    { key: "size", label: "Size" },
    { key: "weight", label: "Weight" },
    { key: "materials", label: "Materials" },
    { key: "colors", label: "Colors" },
  ] },
  { title: "Display", rows: [
    { key: "display", label: "Display" },
  ] },
  { title: "Performance", rows: [
    { key: "chip", label: "Chip" },
  ] },
  { title: "Camera", rows: [
    { key: "mainCamera", label: "Main camera" },
    { key: "frontCamera", label: "Front camera" },
  ] },
  { title: "Battery", rows: [
    { key: "battery", label: "Battery" },
  ] },
  { title: "Connectivity", rows: [
    { key: "connectivity", label: "Connectivity" },
  ] },
];

function ComparePage({ compareIds, onToggleCompare, onClear, go }) {
  const { products: PRODUCTS } = useStoreData();
  const items = compareIds.map((id) => PRODUCTS.find((p) => p.id === id)).filter(Boolean);

  if (items.length === 0) {
    return (
      <div className="max-w-3xl mx-auto px-6 py-28 text-center">
        <Scale size={28} style={{ color: T.mist }} className="mx-auto mb-4" />
        <h1 style={{ color: T.ink }} className="text-2xl font-semibold mb-2">Nothing to compare yet</h1>
        <p style={{ color: T.graphite }} className="text-sm mb-7">Add up to three devices from any product page or catalog card.</p>
        <button onClick={() => go("catalog", { category: "iphone" })} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5">Browse iPhone</button>
      </div>
    );
  }

  function cell(product, key) {
    if (key === "price") return CURRENCY(priceFrom(product));
    if (key === "colors") return (product.colors || []).join(", ") || "—";
    if (key === "condition") return product.hasUnits ? "Certified pre-owned" : "New";
    return product.specs[key] || "—";
  }

  return (
    <div className="max-w-6xl mx-auto px-6 md:px-10 py-12">
      <div className="flex items-end justify-between mb-8">
        <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em", fontSize: "clamp(1.9rem, 3.2vw, 2.75rem)", lineHeight: 1.12 }}>Compare devices</h1>
        <button onClick={onClear} style={{ color: T.ink }} className="text-sm font-medium underline underline-offset-4">Clear all</button>
      </div>

      <div className="overflow-x-auto">
        <table style={{ minWidth: "640px" }} className="w-full border-collapse">
          <thead>
            <tr>
              <th style={{ backgroundColor: T.paper }} className="w-32 sm:w-40 sticky left-0 z-20" />
              {items.map((p) => (
                <th key={p.id} style={{ borderColor: T.line, backgroundColor: T.paper }} className="border-b px-4 pb-6 text-left align-top sticky top-16">
                  <div className="flex flex-col items-start gap-4">
                    <div style={{ backgroundColor: T.stone }} className="relative w-28 h-28 overflow-hidden">
                      <ProductImage product={p} size={92} />
                    </div>
                    <div>
                      <p style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.01em" }} className="text-lg leading-snug">{p.name}</p>
                      <button onClick={() => onToggleCompare(p.id)} style={{ color: T.mist }} className="text-xs mt-1.5 inline-flex items-center gap-1"><X size={11} /> Remove</button>
                    </div>
                    <button onClick={() => go("product", { id: p.id })} style={{ borderColor: T.line, color: T.ink }} className="border px-3.5 py-2 text-xs font-medium">View product</button>
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {COMPARE_GROUPS.map((group) => (
              <React.Fragment key={group.title}>
                <tr>
                  <td style={{ color: T.graphite, backgroundColor: T.paper, fontSize: "11.5px", letterSpacing: "0.08em" }} className="pt-9 pb-2 font-semibold uppercase sticky left-0 z-10">{group.title}</td>
                  {items.map((p) => <td key={p.id} className="pt-9 pb-2" />)}
                </tr>
                {group.rows.map((row) => (
                  <tr key={row.key}>
                    <td style={{ color: T.graphite, borderColor: T.line, backgroundColor: T.paper }} className="border-b py-4 text-sm pr-4 sticky left-0 z-10">{row.label}</td>
                    {items.map((p) => (
                      <td key={p.id} style={{ color: T.ink, borderColor: T.line }} className="border-b py-4 px-4 text-sm">{cell(p, row.key)}</td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ============================================================
   RECOMMENDATION WIZARD
   ============================================================ */
function RecommendationWizard({ go, onAddToCart }) {
  const [step, setStep] = useState(0);
  const [budget, setBudget] = useState(null);
  const [priorities, setPriorities] = useState([]);
  const [size, setSize] = useState(null);
  const [result, setResult] = useState(null);

  const steps = ["Budget", "Priorities", "Size", "Result"];

  function togglePriority(k) {
    setPriorities((prev) => prev.includes(k) ? prev.filter((x) => x !== k) : [...prev, k]);
  }
  function finish(finalSize) {
    const s = finalSize || size;
    const scored = computeRecommendation({ budgetMax: budget.max, priorities, size: s });
    setResult(scored);
    setStep(3);
  }

  return (
    <div className="max-w-2xl mx-auto px-6 py-16">
      <p style={{ color: T.graphite, fontSize: "12.5px", letterSpacing: "0.08em" }} className="uppercase mb-6">Find your iPhone</p>
      <div className="flex items-center gap-6 mb-12">
        {steps.map((s, i) => (
          <div key={s} className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-2">
              <span style={{ color: i <= step ? T.ink : T.mist, fontVariantNumeric: "tabular-nums" }} className="text-xs font-semibold">{String(i + 1).padStart(2, "0")}</span>
              <span style={{ color: i <= step ? T.ink : T.mist }} className="text-xs font-medium truncate hidden sm:inline">{s}</span>
            </div>
            <div style={{ backgroundColor: i <= step ? T.ink : T.line, height: "2px" }} className="w-full" />
          </div>
        ))}
      </div>

      {step === 0 && (
        <div>
          <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-3xl md:text-4xl mb-2">What's your budget?</h1>
          <p style={{ color: T.graphite }} className="text-sm mb-8">We'll only show devices within this range.</p>
          <div className="grid grid-cols-2 gap-3">
            {REC_QUESTIONS.budget.map((b, i) => (
              <button key={b.id} onClick={() => { setBudget(b); setStep(1); }}
                style={{ borderColor: T.line, color: T.ink }} className="group border py-5 px-4 text-left hover:border-black/60 transition-colors">
                <span className="block text-sm font-medium mb-3">{b.label}</span>
                <span style={{ backgroundColor: T.line }} className="block h-[3px] w-full overflow-hidden">
                  <span style={{ backgroundColor: T.ink, width: `${((i + 1) / REC_QUESTIONS.budget.length) * 100}%` }} className="block h-full transition-all" />
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      {step === 1 && (
        <div>
          <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-3xl md:text-4xl mb-2">What matters most?</h1>
          <p style={{ color: T.graphite }} className="text-sm mb-8">Choose as many as you like.</p>
          <div className="grid grid-cols-2 gap-3 mb-10">
            {REC_QUESTIONS.priorities.map((p) => {
              const sel = priorities.includes(p.id);
              return (
                <button key={p.id} onClick={() => togglePriority(p.id)}
                  style={{ borderColor: sel ? T.ink : T.line, backgroundColor: sel ? T.stone : "transparent" }}
                  className="relative border py-4 px-4 text-left transition-colors">
                  <span style={{ color: T.ink }} className="text-sm font-medium">{p.label}</span>
                  {sel && <CircleCheck size={15} style={{ color: T.ink }} className="absolute top-3.5 right-3.5" />}
                </button>
              );
            })}
          </div>
          <div className="flex justify-between">
            <button onClick={() => setStep(0)} style={{ color: T.graphite }} className="text-sm">Back</button>
            <button onClick={() => setStep(2)} disabled={!priorities.length} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5 disabled:opacity-30">Continue</button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div>
          <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-3xl md:text-4xl mb-2">Do you prefer?</h1>
          <p style={{ color: T.graphite }} className="text-sm mb-8">Screen and body size.</p>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-10">
            {REC_QUESTIONS.size.map((s) => (
              <button key={s.id} onClick={() => { setSize(s.id); finish(s.id); }}
                style={{ borderColor: T.line, color: T.ink }} className="border py-5 px-4 text-left sm:text-center hover:border-black/60 transition-colors">
                <span className="block text-sm font-medium">{s.label}</span>
                <span style={{ color: T.graphite }} className="block text-xs mt-1.5">
                  {s.id === "compact" ? "Easier one-handed use" : s.id === "large" ? "More screen for media" : "Show me everything"}
                </span>
              </button>
            ))}
          </div>
          <button onClick={() => setStep(1)} style={{ color: T.graphite }} className="text-sm">Back</button>
        </div>
      )}

      {step === 3 && result && (
        <div>
          {result.length === 0 ? (
            <div className="text-center py-10">
              <p style={{ color: T.ink }} className="text-xl font-medium mb-2">No exact match in this budget</p>
              <p style={{ color: T.graphite }} className="text-sm mb-6">Try a higher budget to see more devices.</p>
              <button onClick={() => setStep(0)} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5">Start over</button>
            </div>
          ) : (
            <div>
              <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-3xl md:text-4xl mb-1">We found your match.</h1>
              <p style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 600, letterSpacing: "-0.01em" }} className="text-lg mb-6">{result[0].name}</p>

              <div style={{ borderColor: T.line }} className="border overflow-hidden mb-4">
                <div style={{ backgroundColor: T.stone }} className="relative aspect-[16/10]">
                  <ProductImage product={result[0]} size={150} />
                </div>
                <div className="p-6 md:p-8">
                  <p style={{ color: T.ink, fontVariantNumeric: "tabular-nums", fontWeight: 700, letterSpacing: "-0.01em" }} className="text-2xl mb-4">{CURRENCY(priceFrom(result[0]))}</p>
                  <div className="flex flex-col gap-2">
                    <p style={{ color: T.graphite }} className="text-sm flex items-center gap-1.5"><Check size={14} style={{ color: T.ok }} /> Fits your budget</p>
                    {priorities.slice(0, 3).map((k) => (
                      <p key={k} style={{ color: T.graphite }} className="text-sm flex items-center gap-1.5 capitalize"><Check size={14} style={{ color: T.ok }} /> Excellent for {k}</p>
                    ))}
                  </div>
                  <button onClick={() => go("product", { id: result[0].id })} style={{ backgroundColor: T.ink }} className="mt-6 text-white text-sm font-medium px-6 py-3 w-full sm:w-auto">View product</button>
                </div>
              </div>

              {result.length > 1 && (
                <div className="mt-10">
                  <p style={{ color: T.ink }} className="text-sm font-medium mb-4">Other good matches</p>
                  <div className="grid grid-cols-2 gap-3">
                    {result.slice(1, 3).map((p) => (
                      <button key={p.id} onClick={() => go("product", { id: p.id })} style={{ borderColor: T.line }} className="border p-4 text-left hover:bg-white">
                        <div style={{ backgroundColor: T.stone }} className="relative w-12 h-12 overflow-hidden">
                          <ProductImage product={p} size={48} />
                        </div>
                        <p style={{ color: T.ink }} className="text-sm font-medium mt-2">{p.name}</p>
                        <p style={{ color: T.graphite }} className="text-xs mt-0.5">{CURRENCY(priceFrom(p))}</p>
                      </button>
                    ))}
                  </div>
                </div>
              )}
              <button onClick={() => { setStep(0); setResult(null); setPriorities([]); }} style={{ color: T.graphite }} className="text-sm mt-8">Start over</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ============================================================
   CART DRAWER
   ============================================================ */
function CartDrawer({ open, onClose, cart, updateQty, removeItem, go }) {
  const { products: PRODUCTS } = useStoreData();
  const subtotal = cart.reduce((s, i) => s + i.unitPrice * i.qty, 0);
  const [mounted, visible] = useMountTransition(open, 300);
  if (!mounted) return null;
  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div
        style={{ backgroundColor: "rgba(18,18,16,0.4)", opacity: visible ? 1 : 0, transition: "opacity 250ms ease" }}
        className="absolute inset-0" onClick={onClose}
      />
      <div
        style={{
          backgroundColor: T.paper,
          transform: visible ? "translateX(0)" : "translateX(100%)",
          transition: "transform 300ms cubic-bezier(0.22, 1, 0.36, 1)",
          boxShadow: "-8px 0 30px rgba(18,18,16,0.08)",
        }}
        className="relative w-full max-w-sm h-full flex flex-col"
      >
        <div className="flex items-center justify-between px-6 h-16" style={{ borderBottom: `1px solid ${T.line}` }}>
          <h2 style={{ color: T.ink }} className="text-base font-semibold">Your bag</h2>
          <button onClick={onClose} style={{ color: T.ink }} className="p-2 -m-2"><X size={20} /></button>
        </div>

        {cart.length === 0 ? (
          <div className="flex-1 flex items-center justify-center flex-col gap-3 px-6">
            <ShoppingBag size={24} style={{ color: T.mist }} />
            <p style={{ color: T.graphite }} className="text-sm">Your bag is empty.</p>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto px-6 py-5 flex flex-col gap-5">
            {cart.map((item) => (
              <div key={item.key} className="flex gap-4">
                <div style={{ backgroundColor: T.stone }} className="relative w-16 h-16 shrink-0 overflow-hidden">
                  <ProductImage product={PRODUCTS.find((p) => p.id === item.productId)} size={38} />
                </div>
                <div className="flex-1 min-w-0">
                  <p style={{ color: T.ink }} className="text-sm font-medium truncate">{item.name}</p>
                  {item.variantLabel && <p style={{ color: T.graphite }} className="text-xs mt-0.5">{item.variantLabel}</p>}
                  {item.isPreorder && <Badge tone="brass">Pre-order</Badge>}
                  <div className="flex items-center justify-between mt-2">
                    {item.maxQty > 1 ? (
                      <div style={{ borderColor: T.line }} className="inline-flex items-center border">
                        <button onClick={() => updateQty(item.key, -1)} className="px-2.5 py-1.5"><Minus size={12} /></button>
                        <span className="px-2.5 text-xs font-medium">{item.qty}</span>
                        <button onClick={() => updateQty(item.key, 1)} className="px-2.5 py-1.5"><Plus size={12} /></button>
                      </div>
                    ) : <span style={{ color: T.mist }} className="text-xs">Qty 1 · unique unit</span>}
                    <span style={{ color: T.ink, fontVariantNumeric: "tabular-nums" }} className="text-sm font-medium">{CURRENCY(item.unitPrice * item.qty)}</span>
                  </div>
                </div>
                <button onClick={() => removeItem(item.key)} style={{ color: T.mist }} className="p-2 -m-2 h-fit"><Trash2 size={15} /></button>
              </div>
            ))}
          </div>
        )}

        {cart.length > 0 && (
          <div style={{ borderColor: T.line }} className="border-t px-6 py-5">
            <div className="flex items-center justify-between mb-4">
              <span style={{ color: T.graphite }} className="text-sm">Subtotal</span>
              <span style={{ color: T.ink, fontVariantNumeric: "tabular-nums" }} className="text-base font-medium">{CURRENCY(subtotal)}</span>
            </div>
            <button onClick={() => { onClose(); go("checkout"); }} style={{ backgroundColor: T.ink }} className="w-full text-white text-sm font-medium py-3.5">Checkout</button>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================================================
   CHECKOUT PAGE
   ============================================================ */
function CheckoutPage({ cart, go, onPlaceOrder }) {
  const { products: PRODUCTS } = useStoreData();
  const [form, setForm] = useState({ name: "", phone: "", email: "", address: "", city: "", notes: "" });
  const [placed, setPlaced] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [orderError, setOrderError] = useState("");
  const subtotal = cart.reduce((s, i) => s + i.unitPrice * i.qty, 0);
  const valid = form.name && form.phone && form.address && form.city;

  if (cart.length === 0 && !placed) {
    return (
      <div className="max-w-md mx-auto px-6 py-28 text-center">
        <p style={{ color: T.ink }} className="text-xl font-medium mb-2">Your bag is empty</p>
        <button onClick={() => go("catalog", { category: "iphone" })} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5 mt-4">Browse devices</button>
      </div>
    );
  }

  if (placed) {
    return (
      <div className="max-w-md mx-auto px-6 py-28 text-center">
        <CircleCheck size={32} style={{ color: T.ok }} className="mx-auto mb-4" />
        <p style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-3xl mb-2">Order placed</p>
        <p style={{ color: T.graphite }} className="text-sm mb-1">Order #{String(placed.id).slice(0, 8).toUpperCase()}</p>
        <p style={{ color: T.graphite }} className="text-sm mb-8">We'll call {placed.phone} to confirm delivery details.</p>
        <button onClick={() => go("home")} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3.5">Continue shopping</button>
      </div>
    );
  }

  async function submit(e) {
    e.preventDefault();
    if (!valid || submitting) return;
    setSubmitting(true);
    setOrderError("");
    try {
      const order = await onPlaceOrder(form);
      setPlaced(order);
    } catch (err) {
      setOrderError(err.message);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="max-w-5xl mx-auto px-6 md:px-10 py-12 flex flex-col md:flex-row gap-14">
      <div className="flex-1 min-w-0">
        <h1 style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 700, letterSpacing: "-0.02em" }} className="text-4xl mb-8">Checkout</h1>
        <form onSubmit={submit} className="flex flex-col gap-4">
          {[
            { k: "name", label: "Full name", req: true },
            { k: "phone", label: "Phone", req: true },
            { k: "email", label: "Email", req: false },
            { k: "address", label: "Address", req: true },
            { k: "city", label: "City", req: true },
          ].map((f) => (
            <div key={f.k}>
              <label style={{ color: T.ink }} className="text-sm font-medium mb-1.5 block">{f.label}{f.req && " *"}</label>
              <input
                value={form[f.k]} onChange={(e) => setForm((s) => ({ ...s, [f.k]: e.target.value }))}
                style={{ borderColor: T.line, color: T.ink }} className="w-full border px-4 py-3 text-sm bg-white outline-none focus:border-black"
              />
            </div>
          ))}
          <div>
            <label style={{ color: T.ink }} className="text-sm font-medium mb-1.5 block">Notes (optional)</label>
            <textarea value={form.notes} onChange={(e) => setForm((s) => ({ ...s, notes: e.target.value }))} rows={3}
              style={{ borderColor: T.line, color: T.ink }} className="w-full border px-4 py-3 text-sm bg-white outline-none focus:border-black" />
          </div>

          <div style={{ borderColor: T.line, backgroundColor: T.stone }} className="border px-4 py-3.5 mt-2">
            <p style={{ color: T.ink }} className="text-sm font-medium">Payment: Cash on delivery</p>
            <p style={{ color: T.graphite }} className="text-xs mt-0.5">Pay when your order arrives. Other methods can be added later.</p>
          </div>

          {orderError && (
            <p role="alert" style={{ color: "#B3261E", backgroundColor: "#FDECEA" }} className="text-sm px-4 py-3">{orderError}</p>
          )}
          <button type="submit" disabled={!valid || submitting} style={{ backgroundColor: T.ink }} className="mt-2 text-white text-sm font-medium py-3.5 disabled:opacity-30">{submitting ? "Placing order…" : "Place order"}</button>
        </form>
      </div>

      <div className="md:w-96 shrink-0">
        <div style={{ borderColor: T.line, backgroundColor: T.stone }} className="border p-6 md:sticky md:top-24">
          <p style={{ color: T.ink }} className="text-sm font-medium mb-4">Order summary</p>
          <div className="flex flex-col gap-4 mb-6">
            {cart.map((item) => (
              <div key={item.key} className="flex items-center gap-3">
                <div style={{ backgroundColor: T.paper }} className="relative w-12 h-12 shrink-0 overflow-hidden">
                  <ProductImage product={PRODUCTS.find((p) => p.id === item.productId)} size={28} />
                </div>
                <div className="flex-1 min-w-0 flex justify-between gap-3 text-sm">
                  <div className="min-w-0">
                    <p style={{ color: T.ink }} className="truncate">{item.name} {item.qty > 1 && `× ${item.qty}`}</p>
                    {item.variantLabel && <p style={{ color: T.graphite }} className="text-xs mt-0.5 truncate">{item.variantLabel}</p>}
                  </div>
                  <span style={{ color: T.ink }} className="shrink-0">{CURRENCY(item.unitPrice * item.qty)}</span>
                </div>
              </div>
            ))}
          </div>
          <div style={{ borderColor: T.line }} className="border-t pt-4 flex justify-between">
            <span style={{ color: T.ink }} className="text-base font-medium">Total</span>
            <span style={{ color: T.ink, fontVariantNumeric: "tabular-nums" }} className="text-base font-medium">{CURRENCY(subtotal)}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   API-BACKED STORE DATA PROVIDER
   The storefront owns no catalog data of its own. Everything —
   products, prices, units, hero slides, homepage content — is
   loaded from the Go iPhone API, which reads the same database the
   Admin app writes to. Edits made in Admin therefore appear here
   within seconds (re-fetched every 30s and whenever the tab regains
   focus). Cart + compare stay in the browser (localStorage) — they
   are per-shopper and not sensitive.
   ============================================================ */
const API_URL = (import.meta.env.VITE_API_URL || "http://localhost:4000").replace(/\/$/, "");

async function apiFetch(path, options = {}) {
  const res = await fetch(`${API_URL}${path}`, {
    headers: { "content-type": "application/json" },
    ...options,
  });
  let data = null;
  try { data = await res.json(); } catch (e) { /* non-JSON body */ }
  if (!res.ok) {
    const err = new Error(data?.error || "Something went wrong. Please try again.");
    err.status = res.status;
    throw err;
  }
  return data;
}

/* Safe defaults so a section the admin hasn't customized still renders. */
function defaultSiteContent() {
  return {
    announcement: { text: "", link: "", visible: false },
    categoryImages: {},
    comparisonSection: {
      image: "", title: "Compare devices", description: "Line up specs, cameras, and pricing across up to three devices at once.",
      cta: "Start comparing", visible: true,
    },
    recommendationSection: {
      image: "", title: "Which iPhone is right for you?", description: "Answer a few questions and we'll match you with the best device for your budget and needs.",
      cta: "Find your perfect device", visible: true,
    },
    designSystem: { preset: "signature", colors: { ink: "#111110", paper: "#FAFAF8", stone: "#F0EEE9", stoneDeep: "#E9E5DD", line: "#E3E0D9", graphite: "#706C64", mist: "#9C978D", brass: "#AD8642", brassSoft: "#D2B060", brassDeep: "#8E6F34" }, fontFamily: "Inter" },
    toolsSection: { visible: true, eyebrow: "Tools", title: "Not sure which to choose?" },
    trustSection: { visible: true, points: [
      { id: "warranty", title: "Every device warrantied", desc: "New and certified pre-owned devices each ship with a Go iPhone warranty.", visible: true },
      { id: "battery", title: "Battery health disclosed", desc: "Pre-owned battery health and condition are graded and shown before you buy.", visible: true },
      { id: "grading", title: "Individually graded", desc: "Each pre-owned unit is inspected on its own, not sold by a generic condition tier.", visible: true },
      { id: "delivery", title: "Cash on delivery", desc: "Pay when your order arrives, anywhere we deliver.", visible: true },
    ] },
    collections: [],
    settings: {},
  };
}

function StoreDataProvider({ children }) {
  const [catalog, setCatalog] = useState({ categories: [], products: [], deviceUnits: [], heroSlides: [], siteContent: defaultSiteContent() });
  const [status, setStatus] = useState("loading"); // loading | ready | error
  const [previewDraft, setPreviewDraft] = useState(null);
  const adminPreview = new URLSearchParams(window.location.search).get("adminPreview") === "1";
  useEffect(() => {
    if (!adminPreview) return;
    const receiveDraft = event => {
      if (event.source !== window.parent || event.data?.type !== "GO_IPHONE_ADMIN_PREVIEW") return;
      const payload = event.data.payload || {};
      setPreviewDraft({
        siteContent: payload.siteContent && typeof payload.siteContent === "object" ? payload.siteContent : null,
        heroSlides: Array.isArray(payload.heroSlides) ? payload.heroSlides : null,
      });
    };
    window.addEventListener("message", receiveDraft);
    return () => window.removeEventListener("message", receiveDraft);
  }, [adminPreview]);

  // Plain mutable mirror so the pure helper functions (unitsFor, priceFrom,
  // computeRecommendation, ...) always read the live catalog.
  store.products = catalog.products;
  store.units = catalog.deviceUnits;
  store.categories = catalog.categories;

  const load = useCallback(async (silent) => {
    try {
      const data = await apiFetch("/api/catalog");
      const d = defaultSiteContent();
      const sc = data.siteContent || {};
      setCatalog({
        categories: data.categories || [],
        products: data.products || [],
        deviceUnits: data.deviceUnits || [],
        heroSlides: data.heroSlides || [],
        siteContent: {
          ...d, ...sc,
          announcement: { ...d.announcement, ...(sc.announcement || {}) },
          comparisonSection: { ...d.comparisonSection, ...(sc.comparisonSection || {}) },
          recommendationSection: { ...d.recommendationSection, ...(sc.recommendationSection || {}) },
          designSystem: { ...d.designSystem, ...(sc.designSystem || {}), colors: { ...d.designSystem.colors, ...(sc.designSystem?.colors || {}) } },
          toolsSection: { ...d.toolsSection, ...(sc.toolsSection || {}) },
          trustSection: { ...d.trustSection, ...(sc.trustSection || {}), points: Array.isArray(sc.trustSection?.points) ? sc.trustSection.points : d.trustSection.points },
        },
      });
      setStatus("ready");
    } catch (e) {
      if (!silent) setStatus("error");
    }
  }, []);

  useEffect(() => {
    load(false);
    const timer = setInterval(() => load(true), 30000);
    const onFocus = () => load(true);
    window.addEventListener("focus", onFocus);
    return () => { clearInterval(timer); window.removeEventListener("focus", onFocus); };
  }, [load]);

  async function addReservation(payload) {
    if (adminPreview) throw new Error("Reservations are disabled in admin preview.");
    await apiFetch("/api/reservations", { method: "POST", body: JSON.stringify(payload) });
  }

  // The server — not this browser — decides prices, checks stock, and claims
  // any specific used device atomically. We only send *what* the shopper wants.
  async function placeOrder(payload) {
    if (adminPreview) throw new Error("Checkout is disabled in admin preview.");
    try {
      const data = await apiFetch("/api/orders", { method: "POST", body: JSON.stringify(payload) });
      load(true);
      return data.order;
    } catch (err) {
      if (err.status === 409) load(true); // something sold out — refresh what's on offer
      throw err;
    }
  }

  const value = {
    products: catalog.products,
    units: catalog.deviceUnits,
    categories: catalog.categories,
    heroSlides: previewDraft?.heroSlides || catalog.heroSlides,
    siteContent: previewDraft?.siteContent ? {
      ...catalog.siteContent,
      ...previewDraft.siteContent,
      designSystem: { ...catalog.siteContent.designSystem, ...(previewDraft.siteContent.designSystem || {}), colors: { ...catalog.siteContent.designSystem?.colors, ...(previewDraft.siteContent.designSystem?.colors || {}) } },
      toolsSection: { ...catalog.siteContent.toolsSection, ...(previewDraft.siteContent.toolsSection || {}) },
      trustSection: { ...catalog.siteContent.trustSection, ...(previewDraft.siteContent.trustSection || {}) },
    } : catalog.siteContent,
    status, reload: () => load(false),
    addReservation, placeOrder,
  };
  return <StoreDataContext.Provider value={value}>{children}</StoreDataContext.Provider>;
}

/* ============================================================
   APP ROOT
   ============================================================ */
function AppShell() {
  const { placeOrder, siteContent } = useStoreData();
  const designSystem = siteContent.designSystem || {};
  const designColors = designSystem.colors || {};
  Object.assign(T, {
    ink: designColors.ink || "#111110", paper: designColors.paper || "#FAFAF8",
    stone: designColors.stone || "#F0EEE9", stoneDeep: designColors.stoneDeep || "#E9E5DD",
    line: designColors.line || "#E3E0D9", graphite: designColors.graphite || "#706C64",
    mist: designColors.mist || "#9C978D", brass: designColors.brass || "#AD8642",
    brassSoft: designColors.brassSoft || "#D2B060", brassDeep: designColors.brassDeep || "#8E6F34",
  });
  const [view, setView] = useState("home");
  const [params, setParams] = useState({});
  const [cart, setCart] = useState([]);
  const [compareIds, setCompareIds] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    try { const c = localStorage.getItem("go-iphone-cart"); if (c) setCart(JSON.parse(c)); } catch (e) { /* private mode / corrupt value */ }
    try { const cmp = localStorage.getItem("go-iphone-compare"); if (cmp) setCompareIds(JSON.parse(cmp)); } catch (e) { /* ignore */ }
    setReady(true);
  }, []);

  useEffect(() => {
    if (!ready) return;
    try { localStorage.setItem("go-iphone-cart", JSON.stringify(cart)); } catch (e) { /* storage full/blocked */ }
  }, [cart, ready]);

  useEffect(() => {
    if (!ready) return;
    try { localStorage.setItem("go-iphone-compare", JSON.stringify(compareIds)); } catch (e) { /* storage full/blocked */ }
  }, [compareIds, ready]);

  function go(v, p = {}) {
    setView(v);
    setParams(p);
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  }

  function onToggleCompare(id) {
    setCompareIds((prev) => {
      if (prev.includes(id)) return prev.filter((x) => x !== id);
      if (prev.length >= 3) return prev;
      return [...prev, id];
    });
  }

  function onAddToCart(item) {
    setCart((prev) => {
      const existing = prev.find((i) => i.key === item.key);
      if (existing) {
        return prev.map((i) => i.key === item.key ? { ...i, qty: Math.min(i.qty + item.qty, item.maxQty) } : i);
      }
      return [...prev, item];
    });
    setCartOpen(true);
  }

  function updateQty(key, delta) {
    setCart((prev) => prev.map((i) => i.key === key ? { ...i, qty: Math.max(1, Math.min(i.qty + delta, i.maxQty)) } : i).filter(Boolean));
  }
  function removeItem(key) {
    setCart((prev) => prev.filter((i) => i.key !== key));
  }
  async function onPlaceOrder(form) {
    // Send only WHAT was chosen — the server looks up prices and checks stock.
    const items = cart.map((i) => ({
      productId: i.productId,
      inventoryUnitId: i.unitId || null,
      storage: i.storage || null,
      color: i.color || null,
      qty: i.qty,
    }));
    const order = await placeOrder({
      name: form.name.trim(), phone: form.phone.trim(), email: form.email.trim() || null,
      address: form.address.trim(), city: form.city.trim(), notes: form.notes?.trim() || null, items,
    });
    setCart([]);
    return { ...order, phone: form.phone };
  }

  return (
    <div style={{ backgroundColor: T.paper, color: T.ink, fontFamily: designSystem.fontFamily === "Georgia" ? "Georgia, serif" : designSystem.fontFamily === "Arial" ? "Arial, sans-serif" : FONT_UI }} className="min-h-screen">
      <style>{`
        @import url('${FONTS_HREF}');
        button { letter-spacing: 0.01em; }
        body, .min-h-screen { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
        input, textarea, select { font-family: ${FONT_UI}; }
        @keyframes heroFadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .hero-fade { animation: heroFadeIn 750ms cubic-bezier(0.22, 1, 0.36, 1); }
      `}</style>
      <AnnouncementBar go={go} />
      <Navbar go={go} cartCount={cart.reduce((s, i) => s + i.qty, 0)} compareCount={compareIds.length} onSearch={() => setSearchOpen(true)} onCart={() => setCartOpen(true)} />

      {view === "home" && <HomePage go={go} compareIds={compareIds} onToggleCompare={onToggleCompare} />}
      {view === "catalog" && <CatalogPage category={params.category || "iphone"} go={go} compareIds={compareIds} onToggleCompare={onToggleCompare} />}
      {view === "product" && <ProductDetailPage productId={params.id} go={go} onAddToCart={onAddToCart} compareIds={compareIds} onToggleCompare={onToggleCompare} />}
      {view === "compare" && <ComparePage compareIds={compareIds} onToggleCompare={onToggleCompare} onClear={() => setCompareIds([])} go={go} />}
      {view === "recommend" && <RecommendationWizard go={go} onAddToCart={onAddToCart} />}
      {view === "checkout" && <CheckoutPage cart={cart} go={go} onPlaceOrder={onPlaceOrder} />}

      <Footer go={go} />
      {compareIds.length > 0 && view !== "compare" && <div className="h-16" />}
      <CompareTray compareIds={compareIds} onClear={() => setCompareIds([])} go={go} />
      <CartDrawer open={cartOpen} onClose={() => setCartOpen(false)} cart={cart} updateQty={updateQty} removeItem={removeItem} go={go} />
      {searchOpen && <SearchOverlay onClose={() => setSearchOpen(false)} go={go} />}
    </div>
  );
}

function StoreGate() {
  const { status, reload } = useStoreData();
  if (status === "loading") {
    return (
      <div style={{ backgroundColor: T.paper }} className="min-h-screen flex items-center justify-center">
        <BrandMark size={44} />
      </div>
    );
  }
  if (status === "error") {
    return (
      <div style={{ backgroundColor: T.paper }} className="min-h-screen flex flex-col items-center justify-center gap-4 px-6 text-center">
        <BrandMark size={44} />
        <p style={{ color: T.ink }} className="text-lg font-medium">We couldn't load the store.</p>
        <p style={{ color: T.graphite }} className="text-sm">Please check your connection and try again.</p>
        <button onClick={reload} style={{ backgroundColor: T.ink }} className="text-white text-sm font-medium px-7 py-3">Try again</button>
      </div>
    );
  }
  return <AppShell />;
}

export default function App() {
  return (
    <StoreDataProvider>
      <StoreGate />
    </StoreDataProvider>
  );
}
